const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.grid}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v==null?'—':Number(v).toLocaleString('ru-RU',{maximumFractionDigits:1});
const money=v=>v===null?'—':Number(v).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2});
const date=(v,withDate=false)=>new Date(v).toLocaleString('ru-RU',{timeZone:'Europe/Minsk',...(withDate?{day:'numeric',month:'short'}:{}),hour:'2-digit',minute:'2-digit'});
const relative=v=>{const m=Math.max(0,Math.floor((Date.now()-new Date(v))/60000));return m<1?'только что':m<60?`${m} мин. назад`:m<1440?`${Math.floor(m/60)} ч. назад`:date(v,true);};
const key=()=>crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(24)),x=>x.toString(16).padStart(2,'0')).join('');
let secureAuth=false,csrfToken='',reviewProposal=null,metricDraft=null;
let data=null,page=location.hash.slice(1)||'overview',period='week',department='all',product='all',chartTab='orders',taskFilter='all',flowStage='all',flowQuery='',flowPage=0,auditQuery='',taskQuery='',mobile=false;
let market='all',region='all',fromDate='',toDate='',metricView='period',metricDimension='market',employeeId='all',dashboardDraft=[];
let pendingKey=key(),currentOverlay=null,refreshing=false;
const pageNames={overview:'Дашборд',employees:'Сотрудники',sales:'Продажи и клиенты',production:'Производство',finance:'Финансы и люди',flow:'Сквозной поток',decisions:'Реестр решений',audit:'Журнал событий',integrations:'Источники данных',dictionary:'Словарь KPI'};
if(!pageNames[page])page='overview';
const statusNames={new:'Новое',in_progress:'В работе',review:'На проверке',done:'Проверено'};
const sourceNames={filesystem:'Filesystem',bitrix:'Битрикс24',crm:'Битрикс24',erp:'ERP',support:'Омниканал',finance:'1С',hr:'HR'};
const canManage=()=>['executive','manager'].includes(data?.actor.role);
const canExport=()=>canManage()||data?.actor.role==='analyst';
const owner=id=>data.owners.find(o=>o.id===id)||{name:'Система',initials:'С',department:'Контур'};
const avatar=id=>`<span class="avatar">${esc(owner(id).initials)}</span>`;
const ownerInline=id=>`<span class="owner-inline">${avatar(id)}${esc(owner(id).name)}</span>`;
const pill=(label,type='',dot=false)=>`<span class="pill ${type}">${dot?'<i class="dot"></i>':''}${esc(label)}</span>`;
const metric=id=>data.kpis.find(k=>k.id===id);
const empty=(title,description='')=>`<div class="empty">${icon('check')}<h3>${esc(title)}</h3><p>${esc(description)}</p></div>`;
const activeSignals=()=>data.signals.filter(s=>s.status!=='resolved');
const params=()=>new URLSearchParams({period,department,product,market,region,...(period==='custom'?{from:fromDate,to:toDate}:{})});

async function api(path,options={}) {
  let response;try{response=await fetch(path,{...options,signal:options.signal||AbortSignal.timeout(15000),headers:{'content-type':'application/json',...(csrfToken?{'x-csrf-token':csrfToken}:{}),...(options.method&&options.method!=='GET'?{'idempotency-key':options.key||key()}:{}),...options.headers},...(options.body?{body:JSON.stringify(options.body)}:{})});}catch(error){throw new Error(error.name==='TimeoutError'?'Сервер не ответил за 15 секунд. Черновик сохранён; повторите запрос.':'Нет связи с сервером. Черновик сохранён; проверьте сеть и повторите запрос.');}
  let body;try{body=await response.json();}catch{throw new Error('Сервер вернул непонятный ответ. Повторите запрос.');}
  if(!response.ok){const error=new Error(body.error||'Не удалось выполнить запрос.');error.code=body.code;error.status=response.status;throw error;}
  return body;
}
async function load(){data=await api('/api/bootstrap?'+params());department=data.filters.department;product=data.filters.product;fromDate=data.filters.from;toDate=data.filters.to;render();}
async function init(){
  try{const config=await api('/api/auth/config');secureAuth=config.mode==='authenticated';if(secureAuth){const me=await api('/api/auth/me');csrfToken=me.csrf;}await load();const proposal=new URLSearchParams(location.search).get('proposal');if(proposal&&secureAuth)await openProposal(proposal);}catch(error){
    if(secureAuth&&error.status===401){renderLogin();return;}
    if(error.status===401){try{await api('/api/session',{method:'POST',body:{role:['executive','maxim','sergey','operator','support_staff','growth_staff','analyst'].includes(localStorage.getItem('contour-role'))?localStorage.getItem('contour-role'):'executive'}});await load();return;}catch(e){error=e;}}
    document.querySelector('#app').innerHTML=`<div class="boot">${icon('alert')}<h2>Не удалось загрузить контур</h2><p>${esc(error.message)}</p><button class="btn btn-primary" data-action="reload">Повторить</button></div>`;
  }
}
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'alert':'check')+`<span>${esc(message)}</span>`;document.querySelector('#toasts').append(el);setTimeout(()=>el.remove(),6500);}
function nav(id,label,ico,badge=''){if(!data.actor.pages.includes(id))return '';return `<a href="#${id}" class="nav-link ${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ico)}${label}${badge?`<span class="nav-badge">${badge}</span>`:''}</a>`;}
function render(){
 document.title=pageNames[page]+' · Фотопринт Контур';
 const actor=data.actor;
 if(!actor.pages.includes(page)){page='overview';history.replaceState(null,'','#overview');}
 document.querySelector('#app').innerHTML=`<div class="layout">
 <aside id="main-navigation" class="sidebar ${mobile?'mobile-open':''}" aria-label="Основная навигация">
  <a class="brand" href="#overview"><span class="brand-mark"><svg viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="2.3"><circle cx="15" cy="20" r="7"/><circle cx="25" cy="20" r="7"/><path d="M15 8v24M25 8v24"/></svg></span><div><div class="brand-name">фотопринт</div><div class="brand-sub">контур управления</div></div></a>
  <div class="workspace"><div class="workspace-icon">${icon('building')}</div><div><strong>Рабочее пространство</strong><span>ООО «Фотопринт»</span></div></div>
  <div class="section-label">Управление</div>
  <nav class="nav">${nav('overview','Дашборд','grid')}${nav('sales','Продажи и клиенты','chart')}${nav('production','Производство','factory')}${nav('employees','Сотрудники','team')}${actor.role!=='operator'?nav('finance','Финансы и люди','percent'):''}${nav('flow','Сквозной поток','flow')}${nav('decisions','Решения','decisions',data.tasks.filter(t=>t.status!=='done').length||'')}${nav('audit','Журнал событий','activity')}</nav>
  <div class="nav-divider"></div><div class="section-label">Система</div><nav class="nav">${nav('integrations','Источники данных','plug')}${nav('dictionary','Словарь KPI','book')}</nav>
  <div class="sidebar-footer"><div class="system-online"><i class="dot"></i>Контур работает<span>v1.0</span></div><div class="sidebar-profile"><span class="avatar">${actor.initials}</span><div><strong>${esc(actor.name)}</strong><small>${esc(actor.title)}</small></div>${icon('down')}</div></div>
 </aside>
 <div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" data-action="menu" aria-controls="main-navigation" aria-expanded="${mobile}" aria-label="${mobile?'Закрыть меню':'Открыть меню'}">${icon('menu')}</button><span>Рабочее пространство</span>${icon('right')}<strong>${pageNames[page]}</strong></div><div class="top-actions"><button class="icon-button theme-toggle" data-action="theme" aria-label="${document.documentElement.dataset.theme==='dark'?'Включить светлую тему':'Включить тёмную тему'}" title="${document.documentElement.dataset.theme==='dark'?'Светлая тема':'Тёмная тема'}">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button><button class="search-trigger" data-action="search" aria-label="Поиск по контуру">${icon('search')}<span>Поиск по контуру</span><kbd>⌘ K</kbd></button><i class="top-divider"></i><span class="demo-chip"><i class="dot"></i>Демо</span><button class="icon-button" data-action="signals" aria-label="Сигналы, требующие внимания">${icon('bell')}${activeSignals().length?'<span class="notification-dot"></span>':''}</button><i class="top-divider"></i>${secureAuth?`<button class="btn" data-action="proposals">${icon('decisions')}Изменения</button><button class="icon-button" data-action="access" aria-label="Доступ агента">${icon('plug')}</button><button class="icon-button" data-action="logout" aria-label="Выйти">${icon('logout')}</button>`:`<label><span class="sr-only">Демонстрационная роль</span><select id="role-select" class="role-select">${[1,2,3].map(level=>`<optgroup label="${['','Директор','Руководители направлений','Линейные сотрудники'][level]}">${data.roles.filter(r=>r.level===level).map(r=>`<option value="${r.key}" ${r.key===actor.key?'selected':''}>${esc(r.name)} · ${esc(r.title)}</option>`).join('')}</optgroup>`).join('')}</select></label>`}</div></header>
 <main class="content" id="main-content">${renderPage()}<footer class="page-footer"><span class="footer-brand">© 2026 Фотопринт · Контур управления</span><span>${icon('lock')}Демоданные · Filesystem / CSV</span></footer></main></div></div>`;
 enhanceSelects();hideReadonlyControls();

}
function pageHead(title,description,actions=''){
 return `<div class="page-head"><div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div><div class="head-actions">${actions}</div></div>`;
}
function filters(prefix=''){return `<div class="global-filters"><span>${icon('filter')}Срез данных</span>${marketControl()}<label><span class="sr-only">Подразделение</span><select class="period-select" data-filter="department" id="${prefix}department-filter">${data.departments.length>1?'<option value="all">Все подразделения</option>':''}${data.departments.map(d=>`<option value="${d.id}" ${department===d.id?'selected':''}>${d.name}</option>`).join('')}</select></label><label><span class="sr-only">Продукт</span><select class="period-select" data-filter="product" id="${prefix}product-filter"><option value="all">Все продукты</option>${data.products.map(p=>`<option value="${p.id}" ${product===p.id?'selected':''}>${p.name}</option>`).join('')}</select></label>${region!=='all'?`<button class="filter-chip" data-action="region" data-id="all">${esc(data.geography.find(r=>r.id===region)?.name||region)}${icon('close')}</button>`:''}<span class="filter-scope">${data.actor.scope==='all'?'Все направления':icon('lock')+'Мои направления'} · UTC+3</span></div>`;}
function marketControl(){return `<div class="market-toggle" role="group" aria-label="Рынок">${[['all','Все рынки'],['BY','РБ'],['RU','РФ']].map(([id,label])=>`<button type="button" data-action="market" data-id="${id}" aria-pressed="${market===id}" class="${market===id?'active':''}">${label}</button>`).join('')}</div>`;}
function periodControl(prefix=''){return `<div class="period-control"><label><span class="sr-only">Период</span><select class="period-select" data-filter="period" id="${prefix}period-filter">${[['today','Сегодня'],['week','Последние 7 дней'],['month','Последние 28 дней'],['custom','Выбрать даты']].map(([id,name])=>`<option value="${id}" ${period===id?'selected':''}>${name}</option>`).join('')}</select></label>${period==='custom'?`<form class="date-range" data-date-range><input type="date" name="from" aria-label="Начало периода" required value="${fromDate}"><span>—</span><input type="date" name="to" aria-label="Конец периода" required value="${toDate}"><button type="submit" class="btn" aria-label="Применить даты">${icon('check')}</button></form>`:''}</div>`;}
function standardActions(){return `${periodControl()}${canExport()?`<button class="btn" data-action="export">${icon('download')}Экспорт</button>`:''}`;}
function renderPage(){switch(page){case 'overview':return overview();case 'sales':return sales();case 'employees':return employees();case 'production':return production();case 'finance':return finance();case 'flow':return flow();case 'decisions':return decisions();case 'integrations':return integrations();case 'audit':return audit();case 'dictionary':return dictionary();}}
function sparkline(series,negative=false,id=''){
 const valid=series.filter(v=>v!==null&&Number.isFinite(v));if(!valid.length)return '';
 const min=Math.min(...valid),max=Math.max(...valid),points=series.map((v,i)=>v===null?null:[i*77/Math.max(1,series.length-1),32-(v-min)/(max-min||1)*25]),color=negative?'#d2ae79':'#8da891';
 return `<svg class="sparkline" viewBox="0 0 77 35" aria-hidden="true">${splitPlot(points).map(ps=>`<polyline points="${ps.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linejoin="round"/>`).join('')}</svg>`;
}

function metricCard(k){if(!k)return `<div class="metric-card"><div class="metric-title">Закрытый показатель${icon('lock')}</div><div class="readonly">Доступен руководителю</div></div>`;return `<button class="metric-card ${k.trend==='negative'?'attention':''}" data-action="metric" data-id="${k.id}" aria-label="${k.label}: ${k.value}${k.unit}. Открыть формулу и детализацию"><div class="metric-title"><span>${k.label}</span>${icon(k.icon)}</div><span class="metric-source ${k.sourceInfo?.id==='metabase'?'metabase':''}">${icon('plug')}${esc(k.sourceInfo?.name||'Filesystem')}</span><div class="metric-main"><div class="metric-number">${k.value}<span class="metric-unit">${k.unit}</span></div>${sparkline(k.series,k.trend==='negative',k.id)}</div><div class="metric-bottom"><span class="delta ${k.trend}">${icon(k.trend==='negative'?'arrowDown':'arrowUp')}${k.change}</span><span class="metric-description">${k.description}</span></div><div class="metric-plan"><span>План <b>${esc(k.plan)}</b></span><span>Прогноз <b>${esc(k.forecast)}</b></span></div></button>`;}
function metrics(ids){return `<div class="metrics-grid">${ids.filter(id=>metric(id)).map(id=>metricCard(metric(id))).join('')}</div>`;}
function overview(){
 const actor=data.actor,n=activeSignals().length;
 const sub=actor.role==='executive'?'Компания':actor.role==='manager'?actor.name+' · '+actor.focus:actor.name+' · '+actor.title;
 const other=data.kpis.filter(k=>!data.dashboard.metrics.includes(k.id));
 return pageHead('Дашборд',sub,`<button class="btn" data-action="dashboard-edit">${icon('grid')}Настроить дашборд</button>`+standardActions())+filters()+
 `<div class="dashboard-context"><span class="level-badge">${icon(actor.level===1?'building':actor.level===2?'users':'userPlus')}Уровень ${actor.level} · ${actor.role==='analyst'?'Аналитик / администратор':['','Директор','Руководитель направления','Линейный сотрудник'][actor.level]}</span><button class="btn-link status-meta" data-action="refresh"><i class="dot"></i>${date(data.lastUpdated)}${icon('refresh')}</button></div>`+
 metrics(data.dashboard.metrics)+
 `<div class="dashboard-chart">${pulseChart()}</div>`+
 (actor.role==='analyst'?sourceQualityPanel():actor.role!=='operator'?staffOverview():employeePanel())+
 (actor.role==='executive'?performancePanel():'')+
 (actor.role!=='operator'?forecastPanel():'')+
 (other.length?`<details class="more-metrics"><summary>Все показатели <span>${data.kpis.length}</span>${icon('down')}</summary><div class="metrics-grid">${other.map(metricCard).join('')}</div></details>`:'')+
 (n?signalsTable():'')+(actor.role==='executive'?sourcesStrip():'');
}
function performancePanel(){
 const p=data.performance;if(!p)return '';
 return `<section class="panel performance-panel"><div class="panel-header"><div><h2 class="panel-title">Эффективность менеджеров</h2><p class="panel-subtitle">Mary и сотрудники · отдельный недельный демосценарий · без фильтров рынка и периода</p></div><span class="pill good">Среднее сотрудников ${fmt(p.averageRate)} задач/ч</span></div><div class="performance-content"><div class="mary-card"><div class="mary-top"><span class="mary-avatar">M<span>✦</span></span><div><h3>Mary</h3><span>AI-менеджер</span></div><span class="agent-badge">AGENT</span></div><div class="mary-score">×${fmt(p.multiplier)}<span>к производительности<br>сотрудников</span></div><div class="mary-stats"><div><strong>${fmt(p.agent.rate)}</strong><span>задач / час</span></div><div><strong>${fmt(p.agent.completed)}</strong><span>завершено</span></div><div><strong>${fmt(p.agent.hours)}</strong><span>рабочих часов</span></div></div></div><div class="manager-table"><table><thead><tr><th>Менеджер</th><th>Задач / час</th><th>Завершено</th><th>Часы</th></tr></thead><tbody>${p.employees.map(e=>`<tr><td><span class="manager-name">${avatar(e.id)}<span><strong>${e.name}</strong><small>${e.direction}</small></span></span></td><td><div class="rate-cell"><strong>${fmt(e.rate)}</strong><span class="rate-track"><i style="width:${e.rate/p.agent.rate*100}%"></i></span></div></td><td>${fmt(e.completed)}</td><td>${fmt(e.hours)}</td></tr>`).join('')}</tbody></table><p class="performance-note">${icon('info')}Mary: ${fmt(p.agent.completed)} / ${fmt(p.agent.hours)} = ${fmt(p.agent.rate)} задач/ч. Сотрудники: ${fmt(p.averageRate)} задач/ч. Отношение: ${fmt(p.multiplier)}.</p></div></div></section>`;
}
function directionPanel(){
 if(data.actor.key==='maxim')return `<div class="direction-grid"><section class="panel direction-card"><div class="section-head"><h2>Клиентский сервис</h2>${icon('headphones')}</div><div class="direction-stats"><div><strong>${data.totals.tickets}</strong><span>обращений</span></div><div><strong>${metric('support').value}%</strong><span>в рамках SLA</span></div><div><strong>${data.tasks.filter(t=>t.status!=='done').length}</strong><span>открытых решений</span></div></div><a class="btn-link" href="#sales">Продажи и клиенты${icon('arrow')}</a></section><section class="panel direction-card"><div class="section-head"><h2>Каналы</h2>${icon('chart')}</div>${data.channels.map(c=>`<div class="channel"><div><strong>${c.name}</strong><span>${c.orders} заказов · ${c.share}%</span></div><div class="channel-bar"><i style="width:${c.share}%"></i></div></div>`).join('')}</section></div>`;
 return forecastPanel();
}
function employeePanel(){return `<section class="panel employee-work"><div class="panel-header"><h2 class="panel-title">Мои задачи</h2><a class="btn-link" href="#decisions">Открыть список${icon('arrow')}</a></div><div class="employee-tasks">${data.tasks.filter(t=>t.status!=='done').map(t=>`<button data-action="task" data-id="${t.id}" class="employee-task"><span>${icon('decisions')}<strong>${esc(t.title)}</strong></span>${pill(statusNames[t.status],t.status==='review'?'warning':'blue')}<span>${date(t.dueAt,true)}</span>${icon('right')}</button>`).join('')||'<p class="empty-work">Нет открытых задач</p>'}</div></section>`;}
let plotSequence=0;
function curve(points){return points.map((p,i)=>i?`C ${(points[i-1][0]+p[0])/2} ${points[i-1][1]}, ${(points[i-1][0]+p[0])/2} ${p[1]}, ${p[0]} ${p[1]}`:`M ${p[0]} ${p[1]}`).join(' ');}
function pulseChart(){
 if(data.actor.role==='operator')chartTab='orders';
 if(chartTab==='orders'&&metric('orders')?.sourceError)return `<section class="panel main-chart-panel"><div class="panel-header"><h2 class="panel-title">Заказы и прогноз · Metabase</h2>${data.actor.role!=='operator'?'<button class="btn" data-action="chart" data-id="customers">Клиенты</button>':''}</div>${empty('Источник недоступен',metric('orders').sourceError)}</section>`;
 const series=data.series,vals=series.map(s=>s[chartTab]),future=data.seriesForecast.map(s=>s[chartTab]);
 const previous=series.map(s=>s.previous),max=Math.ceil(Math.max(...vals,...future,...(chartTab==='orders'?previous:[]),1)*1.15/10)*10;
 const uid='plot-'+(++plotSequence),width=1080,height=325,pad=55,bottom=274,count=vals.length+future.length;
 const x=i=>pad+i*(width-pad-28)/(count-1),y=v=>bottom-v/max*225;
 const actual=vals.map((v,i)=>[x(i),y(v)]),pred=[actual.at(-1),...future.map((v,i)=>[x(vals.length+i),y(v)])],split=x(vals.length-1);
 const forecastLabel=data.filters.days===1?'3 ч':fmt(data.filters.days/data.series.length)+' дн';
 return `<section class="panel main-chart-panel"><div class="panel-header"><div><h2 class="panel-title">${chartTab==='orders'?'Заказы':'Клиенты'} и прогноз</h2><p class="panel-subtitle">${data.actor.role==='operator'?'Мой участок':data.actor.focus} · ${data.filters.from} — ${data.filters.to}</p></div><div class="segmented"><button data-action="chart" data-id="orders" class="${chartTab==='orders'?'active':''}">Заказы</button>${data.actor.role!=='operator'?`<button data-action="chart" data-id="customers" class="${chartTab==='customers'?'active':''}">Клиенты</button>`:''}</div></div><div class="chart-summary"><strong>${fmt(chartTab==='orders'?(metric('orders')?.raw??data.totals.orders):data.totals.customers)}</strong><span class="chart-total-label">за период</span><div class="chart-legend"><span class="legend-item"><i class="legend-line"></i>Факт</span><span class="legend-item"><i class="legend-line forecast"></i>Прогноз</span>${chartTab==='orders'?'<span class="legend-item"><i class="legend-line previous"></i>Предыдущий период</span>':''}</div></div><div class="chart-wrap"><svg class="main-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="${chartTab==='orders'?'Заказы':'Клиенты'}: фактическая кривая и прогноз на четыре интервала"><defs><linearGradient id="${uid}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#27bc82" stop-opacity=".22"/><stop offset="1" stop-color="#27bc82" stop-opacity="0"/></linearGradient><linearGradient id="${uid}-future"><stop stop-color="#bcadee" stop-opacity=".1"/><stop offset="1" stop-color="#b4a2ea" stop-opacity=".02"/></linearGradient></defs><rect x="${split}" y="20" width="${width-split-25}" height="${bottom-20}" rx="12" fill="url(#${uid}-future)"/>${[0,1,2,3,4].map(i=>`<line x1="${pad}" y1="${y(max*i/4)}" x2="${width-25}" y2="${y(max*i/4)}" stroke="#a5b9be" stroke-opacity=".22" stroke-dasharray="3 5"/><text x="${pad-15}" y="${y(max*i/4)+4}" text-anchor="end">${fmt(max*i/4)}</text>`).join('')}<path d="${curve(actual)} L ${split} ${bottom} L ${pad} ${bottom} Z" fill="url(#${uid})"/>${chartTab==='orders'?`<path d="${curve(previous.map((v,i)=>[x(i),y(v)]))}" fill="none" stroke="#9caebc" stroke-width="2" stroke-dasharray="4 7"/>`:''}<path d="${curve(actual)}" fill="none" stroke="#0fa56e" stroke-width="3.5"/><path d="${curve(pred)}" fill="none" stroke="#8e70ca" stroke-width="3" stroke-dasharray="7 6"/><line x1="${split}" y1="20" x2="${split}" y2="${bottom}" stroke="#98a4b2" stroke-dasharray="4 5"/><text x="${split+14}" y="37" class="prediction-caption">Прогноз</text>${[...actual,...pred.slice(1)].map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="white" stroke="${i<vals.length?'#0fa56e':'#8e70ca'}" stroke-width="2"><title>${i<vals.length?series[i].label:'Прогноз +'+(i-vals.length+1)}: ${[...vals,...future][i]}</title></circle><text x="${p[0]}" y="305" text-anchor="middle">${i<vals.length?series[i].label:'+'+(i-vals.length+1)+' × '+forecastLabel}</text>`).join('')}</svg></div><div class="chart-method">${icon('info')}Прогноз: среднее за интервал × (1,06 + 0,12 × шаг). Сценарная оценка.</div></section>`;
}
function health(){
 const watch=data.kpis.filter(k=>k.trend==='negative').length,score=Math.max(0,100-watch*2),segments=[['Клиентский контур',98],['Производство',Math.max(0,100-activeSignals().filter(s=>s.department==='books').length*12)],['Сервис и доставка',Math.round((metric('support').raw+metric('delivery').raw)/2)]];
 return `<section class="panel health-panel"><div class="panel-header"><h2 class="panel-title">Здоровье контура</h2><button class="icon-button" data-action="health-info" aria-label="Как рассчитан индекс здоровья">${icon('info')}</button></div><div class="health-main"><div class="health-ring"><svg viewBox="0 0 110 110"><circle cx="55" cy="55" r="44" stroke="#f1f4ee" fill="none" stroke-width="7"/><circle cx="55" cy="55" r="44" stroke="#9eaf86" fill="none" stroke-width="7" stroke-linecap="round" stroke-dasharray="${score/100*276.46} 276.46"/></svg><div class="health-number"><strong>${score}<span style="display:inline;font-size:14px;margin:0">%</span></strong><span>индекс здоровья</span></div></div><div class="health-description"><strong>${watch?'Система под контролем':'Всё в рабочем ритме'}</strong><p>${watch?`${watch} показателей вне цели. Откройте KPI, чтобы увидеть причину.`:'Ключевые показатели в пределах заданных целей.'}</p></div></div><div class="health-breakdown">${segments.map(([label,value])=>`<div class="health-line"><span><i class="dot"></i>${label}</span><span class="bar"><i style="width:${value}%"></i></span><strong>${value}%</strong></div>`).join('')}</div><div class="health-footer">${icon('target')}Индекс = 100 − 2 × число KPI вне цели</div></section>`;
}
function signalsTable(){return `<section class="panel table-panel" id="signals-section"><div class="table-top"><div class="title-with-count"><h2 class="panel-title">Требуют решения</h2><span class="count-chip">${activeSignals().length}</span></div><button class="btn-link" data-action="navigate" data-id="decisions">Все решения${icon('arrow')}</button></div>${activeSignals().length?`<div class="table-scroll"><table><thead><tr><th>Сигнал</th><th>Приоритет</th><th>Источник</th><th>Ответственный</th><th>Обнаружен</th><th></th></tr></thead><tbody>${activeSignals().map(s=>`<tr class="clickable-row" tabindex="0" role="button" data-action="signal" data-id="${s.id}" aria-label="${esc(s.title)}"><td><div class="signal-cell"><span class="severity-icon ${s.severity}">${icon(s.severity==='critical'?'alert':'clock')}</span><span>${s.title}<small class="signal-id">${s.id} · ${s.orderId}</small></span></div></td><td>${pill(s.severity==='critical'?'Высокий':'Средний',s.severity,true)}</td><td><span class="source-mini"><span>${sourceNames[s.source]}</span>signals.csv</span></td><td>${ownerInline(s.owner)}</td><td style="font-size:9px">${relative(s.createdAt)}</td><td>${icon('right','row-arrow')}</td></tr>`).join('')}</tbody></table></div>`:empty('Нет открытых отклонений','Все решения и результаты проверок доступны в реестре.')}</section>`;}
function sourcesStrip(){return `<section class="panel source-overview"><span class="source-logo green">FS</span><div><h2>${data.connectors.some(c=>c.id==='metabase')?'Filesystem + Metabase':'Filesystem'}</h2><p>Источники метрик · ${data.source.files.length} CSV-файлов · обновлено ${date(data.source.updatedAt)}</p></div><a href="#integrations" class="btn">Управление источниками ${icon('arrow')}</a></section>`;}
function sales(){return pageHead('Продажи и клиенты','Два рынка · регионы, каналы и клиентский опыт',standardActions())+filters()+metrics(['customers','newCustomers','orders','repeat','conversion','revenue','margin','reviewScore'])+geographyPanel()+`<div class="analytics-grid">${pulseChart()}<section class="panel sales-channels"><div class="panel-header"><h2 class="panel-title">Каналы и сегменты</h2>${pill('За период','good')}</div><div class="channel-list">${data.channels.map(c=>`<div class="channel"><div><strong>${c.name}</strong><span>${fmt(c.orders)} заказов · ${c.share}%</span></div><div class="channel-bar"><i style="width:${c.share}%"></i></div></div>`).join('')}</div><div class="segment-summary">${data.segments.map(s=>`<div><span>${s.name}</span><strong>${s.count}</strong></div>`).join('')}</div><div class="average-ticket"><span>Средний чек · BYN</span><strong>${money(data.averageCheck)}</strong><small>Сумма выручки / число заказов выбранного периода</small></div></section></div><section class="panel"><div class="panel-header"><h2 class="panel-title">Воронка выбранного периода</h2><p class="panel-subtitle">Отток: ${displayValue(data.churn)}% — клиенты предыдущего равного периода без заказа в текущем / активные клиенты предыдущего периода</p><span class="panel-subtitle">План лидов → заказы → выпуск · повторные клиенты отдельно</span></div><div class="funnel">${[['Лиды · демоплан',data.conversion?Math.round(data.totals.orders/(data.conversion/100)):0],['Принято заказов',data.totals.orders],['Произведено',data.stageCounts.filter((s,i)=>i>=5).reduce((n,s)=>n+s.count,0)],['Повторные клиенты',Math.round(data.totals.customers*data.repeat/100)]].map(([l,n],i)=>`<div><span>0${i+1}</span><strong>${fmt(n)}</strong><p>${l}</p></div>`).join('')}</div></section>${reviewsPanel()}`;}


function forecastPanel(){
 const weeks=data.forecast;if(!weeks.length)return '';const first=weeks.find(w=>w.gap<0),max=Math.max(...weeks.flatMap(w=>[w.demand,w.capacity]))*1.18;
 const x=i=>90+i*290,y=v=>260-v/max*210,forecast=weeks.map((w,i)=>[x(i),y(w.demand)]),capacity=weeks.map((w,i)=>[x(i),y(w.capacity)]);
 return `<section class="panel forecast-panel"><div class="panel-header"><div><h2 class="panel-title">Спрос и мощности</h2><p class="panel-subtitle">Прогноз на 4 недели</p></div>${pill(first?'Дефицит с '+first.week+'-й недели':'Мощностей достаточно',first?'warning':'good')}</div><div class="chart-wrap forecast-curve"><svg viewBox="0 0 1080 315" class="main-chart" role="img" aria-label="Кривые прогноза спроса и доступной мощности на четыре недели">${[0,1,2,3,4].map(i=>`<line x1="70" y1="${y(max*i/4)}" x2="1010" y2="${y(max*i/4)}" stroke="#a8b6bf" stroke-opacity=".22" stroke-dasharray="4 6"/><text x="53" y="${y(max*i/4)+4}" text-anchor="end">${Math.round(max*i/4)}</text>`).join('')}<path d="${curve(capacity)}" fill="none" stroke="#93a6b8" stroke-width="3"/><path d="${curve(forecast)}" fill="none" stroke="#8e70ca" stroke-width="3.5" stroke-dasharray="8 5"/>${weeks.map((w,i)=>`<circle cx="${x(i)}" cy="${y(w.demand)}" r="5" fill="#fff" stroke="#8e70ca" stroke-width="2"><title>Спрос ${w.demand}, мощность ${w.capacity}, ${w.gap<0?'дефицит':'резерв'} ${Math.abs(w.gap)}</title></circle><text x="${x(i)}" y="${y(w.demand)-14}" text-anchor="middle">${w.demand}</text><text x="${x(i)}" y="291" text-anchor="middle">${w.label}</text>`).join('')}</svg></div><div class="chart-legend"><span class="legend-item"><i class="legend-line forecast"></i>Прогноз спроса</span><span class="legend-item"><i class="legend-line previous"></i>Доступная мощность</span><span class="forecast-note">Единицы продукции / неделя</span></div></section>`;
}
function production(){return pageHead('Производство','Выпуск, качество и загрузка',standardActions())+filters()+metrics(['orders','moderation','production','quality','defects','leadTime','team','staffing'])+forecastPanel()+`<div class="production-summary"><div class="panel"><span>Повторная печать</span><strong>${fmt(data.reprintCount)} <small>заказов</small></strong><p>Число заказов периода с reprinted=true</p></div><div class="panel"><span>Выпуск · план / факт</span><strong>${fmt(data.productionPlan)} / ${fmt(data.productionFact)} <small>ед.</small></strong><p>План = доступные часы / 0,8 ч. на единицу</p></div><div class="panel"><span>Простои оборудования</span><strong>${fmt(data.downtime)} <small>мин.</small></strong><p>Сумма зарегистрированных простоев за период</p></div><div class="panel"><span>Сценарий мощности</span><strong>−10% <small>на 3-й неделе</small></strong><p>Плановое обслуживание · синтетическое допущение</p></div></div>${shiftPanel()}${signalsTable()}`;}
function finance(){
 if(!data.finance)return empty('Раздел недоступен','Финансовые показатели недоступны текущему профилю.');
 const f=data.finance,currency=esc(f.currency);
 return pageHead('Финансы и люди','БДР / БДДС · план, факт и отклонения в '+currency,standardActions())+filters()+metrics(['revenue','margin','team','staffing'])+`<div class="finance-grid">${[['БДР · доходы',f.bdr,'Σ actualIncome / Σ plannedIncome'],['БДР · расходы',f.bdrCost,'Σ actualCost / Σ plannedCost'],['БДДС · поступления',f.bdds,'Σ actualInflow / Σ plannedInflow'],['БДДС · выплаты',f.bddsCost,'Σ actualOutflow / Σ plannedOutflow']].map(([title,v,formula])=>`<section class="panel finance-card"><div class="section-head"><h2>${title}</h2>${pill(v.index===null?'Нет базы плана':Math.abs(v.index-100)<=5?'В пределах ±5%':'Отклонение от плана',v.index===null?'':Math.abs(v.index-100)<=5?'good':'warning')}</div><div class="finance-value">${money(v.fact)}<span> ${currency}</span></div><dl class="resource-list"><div><dt>План</dt><dd>${money(v.plan)} ${currency}</dd></div><div><dt>Отклонение факта</dt><dd>${v.fact-v.plan>0?'+':''}${money(v.fact-v.plan)} ${currency}</dd></div><div><dt>Факт / план</dt><dd>${displayValue(v.index)}%</dd></div></dl><div class="channel-bar"><i style="width:${Math.min(100,v.index||0)}%"></i></div><p>Суммы из finance_entries.csv; исполнение = ${formula} × 100%. Отклонение = факт − план.</p></section>`).join('')}<section class="panel finance-card"><div class="section-head"><h2>Себестоимость и валовая прибыль</h2>${icon('percent')}</div><dl class="resource-list"><div><dt>Оборот</dt><dd>${money(f.turnover)} ${currency}</dd></div><div><dt>Себестоимость</dt><dd>${money(f.cost)} ${currency}</dd></div><div><dt>Валовая прибыль</dt><dd>${money(f.grossProfit)} ${currency}</dd></div><div><dt>Валовая маржа</dt><dd>${fmt(f.margin)}%</dd></div></dl><p>Прибыль = Σ revenue − Σ cost. Маржа = прибыль / оборот × 100%.</p></section><section class="panel finance-card"><div class="section-head"><h2>Штат и доступность</h2>${icon('team')}</div><dl class="resource-list"><div><dt>План смены</dt><dd>${fmt(f.staff)}</dd></div><div><dt>На смене</dt><dd>${fmt(f.actual)}</dd></div><div><dt>Вакансии</dt><dd>${fmt(f.vacancies)}</dd></div><div><dt>Отсутствуют</dt><dd>${fmt(f.absent)}</dd></div></dl></section><section class="panel finance-card"><div class="section-head"><h2>Сверка ERP / 1С</h2>${pill(f.reconciliation.mismatched?'Расхождения':'Совпадает',f.reconciliation.mismatched?'warning':'good',true)}</div><div class="finance-value">${f.reconciliation.matched}<span> / ${f.reconciliation.total}</span></div><dl class="resource-list"><div><dt>Доходы ERP / 1С</dt><dd>${money(f.reconciliation.erpIncome)} / ${money(f.reconciliation.financeIncome)} ${currency}</dd></div><div><dt>Затраты ERP / 1С</dt><dd>${money(f.reconciliation.erpCost)} / ${money(f.reconciliation.financeCost)} ${currency}</dd></div></dl><p>Сверены суммы, валюты и статусы по orderId. Расхождений: ${f.reconciliation.mismatched}.</p><small>orders.csv ↔ finance_entries.csv · общая выборка заказов</small></section></div><div class="info-panel">${icon('info')}<div>${esc(f.periodBasis)} Планы и факты взяты из CSV. Все денежные значения нормированы в BYN; конвертация валют выполняется до импорта. Обновлено ${date(data.source.updatedAt,true)}, UTC+3. Планы по заказам — синтетические демосметы.</div></div>`;
}
function flow(){
 let orders=data.orders.filter(o=>(flowStage==='all'||String(o.stage)===flowStage)&&(!flowQuery||`${o.id} ${o.client} ${o.product}`.toLowerCase().includes(flowQuery.toLowerCase())));const total=orders.length,maxPage=Math.max(0,Math.ceil(total/12)-1);flowPage=Math.min(flowPage,maxPage);orders=orders.slice(flowPage*12,(flowPage+1)*12);
 return pageHead('Заказы','Статусы и история заказов',standardActions())+filters()+`<div class="flow-stages">${data.stages.map((s,i)=>`<button class="stage-card ${flowStage===String(i)?'active':''}" data-action="stage" data-id="${i}"><small>0${i+1}${icon('arrow')}</small><strong>${s}</strong><span>${data.stageCounts[i].count} заказов</span></button>`).join('')}</div><div class="toolbar"><div class="tabs"><button data-action="stage" data-id="all" class="${flowStage==='all'?'active':''}">Все этапы <span>${data.orders.length}</span></button>${flowStage!=='all'?pill(data.stages[Number(flowStage)],'warning'):''}</div><input class="filter-input" id="flow-search" value="${esc(flowQuery)}" placeholder="Найти заказ, клиента или продукт" aria-label="Поиск заказов"></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>Заказ / продукт</th><th>Клиент</th><th>Текущий этап</th><th>Оплата</th><th>Отзывы</th><th>Владелец</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr class="clickable-row" tabindex="0" role="button" data-action="order" data-id="${o.id}" aria-label="Открыть заказ ${o.id}"><td><strong style="color:#546373;font-weight:650">${o.id}</strong><span class="signal-id">${esc(o.product)}</span></td><td style="font-size:9px">${esc(o.client)}</td><td>${pill(o.status,o.stage===3?'warning':o.stage>=7?'good':'blue')}</td><td>${pill(o.payment,o.payment==='Оплачен'?'good':'warning')}</td><td>${o.reviews?.length?`<span class="review-chip">★ ${fmt(o.reviews.reduce((n,r)=>n+r.rating,0)/o.reviews.length)} · ${o.reviews.length}</span>`:'—'}</td><td>${ownerInline(o.owner)}</td><td>${icon('right','row-arrow')}</td></tr>`).join('')}</tbody></table></div>${!orders.length?empty('Заказы не найдены','Измените поиск, продукт или этап.'):''}<div class="pagination"><span>${total?flowPage*12+1:0}–${Math.min((flowPage+1)*12,total)} из ${total}</span><div><button class="btn" data-action="flow-page" data-id="${flowPage-1}" ${flowPage===0?'disabled':''}>Назад</button><button class="btn" data-action="flow-page" data-id="${flowPage+1}" ${flowPage>=maxPage?'disabled':''}>Далее</button></div></div></section>`;
}
function decisions(){let tasks=data.tasks.filter(t=>(taskFilter==='all'||taskFilter==='mine'&&t.owner===data.actor.id||taskFilter==='overdue'&&new Date(t.dueAt)<new Date()&&t.status!=='done')&&(!taskQuery||`${t.id} ${t.title} ${owner(t.owner).name}`.toLowerCase().includes(taskQuery.toLowerCase())));return pageHead('Реестр решений','Задачи, сроки и результаты проверок',canManage()?`<button class="btn btn-primary" data-action="create-task">${icon('plus')}Новое решение</button>`:'')+`<div class="toolbar"><div class="tabs">${[['all','Все решения'],['mine','Мои задачи'],['overdue','Просроченные']].map(([id,label])=>`<button class="${taskFilter===id?'active':''}" data-action="task-filter" data-id="${id}">${label}${id==='all'?`<span>${data.tasks.length}</span>`:''}</button>`).join('')}</div><input class="filter-input" id="task-search" value="${esc(taskQuery)}" placeholder="Найти решение или владельца" aria-label="Поиск решений"></div><div class="board">${['new','in_progress','review','done'].map((status,i)=>`<section class="board-column"><div class="column-head"><i class="dot ${['','blue','yellow','green'][i]}"></i>${statusNames[status]}<span class="count-chip">${tasks.filter(t=>t.status===status).length}</span></div>${tasks.filter(t=>t.status===status).map(t=>`<button class="task-card" data-action="task" data-id="${t.id}"><div class="task-id">${t.id}${icon('right')}</div><h3>${esc(t.title)}</h3>${t.signalId?`<span class="task-signal">${icon('alert')}${t.signalId}</span>`:`<p>${esc(t.description)}</p>`}<div class="task-card-bottom">${ownerInline(t.owner)}<span>${icon('calendar')}${new Date(t.dueAt).toLocaleDateString('ru-RU',{day:'numeric',month:'short'})}</span></div></button>`).join('')||'<div class="column-empty">Пока нет решений</div>'}</section>`).join('')}</div><div class="info-panel">${icon('info')}<div>Решение закрывается только после повторной проверки. Результат проверки сохраняется вместе с порогом, временем и результатом — даже если отклонение осталось.</div></div>`;}
function integrations(){return pageHead('Источники данных','Данные подключаются через адаптеры')+sourceQualityPanel()+`<div class="adapter-flow"><span>${icon('plug')}Источник</span>${icon('arrow')}<span>Адаптер</span>${icon('arrow')}<span>Единая модель данных</span>${icon('arrow')}<span>${icon('grid')}Дашборды</span></div><div class="adapter-grid">${data.connectors.map(c=>`<section class="panel adapter-card ${c.id==='filesystem'||c.status==='connected'?'active-adapter':''}"><div class="connector-top"><span class="source-logo ${c.color}">${c.short}</span>${pill(c.id==='filesystem'||c.status==='connected'?'Активный':c.status==='error'?'Недоступен':'Не подключён',c.id==='filesystem'||c.status==='connected'?'good':'warning')}</div><span class="adapter-kind">${c.kind==='custom'?'Кастомный адаптер':'Встроенный адаптер'}</span><h2>${esc(c.name)}</h2><p>${c.description?esc(c.description):c.id==='filesystem'?'Заказы, клиенты, обращения, сотрудники и решения из CSV-файлов.':'Клиенты и сделки через REST API Битрикс24. Подключение требует серверного webhook.'}</p><div class="adapter-footer">${c.id==='filesystem'?`<span>${data.source.files.length} файлов · CSV UTF-8</span><button class="btn" data-action="refresh">${icon('refresh')}Перечитать</button>`:c.id==='metabase'?'<span>Доступен через сервер приложения</span><button class="btn" data-action="refresh">Обновить</button>':'<span>REST API · настройка на сервере</span>'}</div></section>`).join('')}</div><section class="panel file-panel"><div class="panel-header"><div><h2 class="panel-title">Файлы Filesystem</h2><p class="panel-subtitle">Исходные файлы и схема. Импорт доступен директору; аналитик может скачать данные.</p></div><span class="source-format">CSV / UTF-8</span></div><div class="table-scroll"><table><thead><tr><th>Файл</th><th>Данные</th><th>Записей</th><th>Размер</th><th>Действия</th></tr></thead><tbody>${data.source.files.map(f=>`<tr><td><code>${esc(f.name)}</code></td><td>${fileLabels[f.name]||'Схема данных'}</td><td>${fmt(f.rows)}</td><td>${fmt(f.bytes/1024)} КБ</td><td><div class="file-actions"><button class="btn" data-action="file-download" data-id="${esc(f.name)}" aria-label="Скачать ${esc(f.name)}">${icon('download')}</button>${f.writable?`<label class="btn file-upload">Импорт<input type="file" accept=".csv,text/csv" data-import="${esc(f.name)}" aria-label="Импорт ${esc(f.name)}"></label>`:'<span class="readonly-file">Чтение</span>'}</div></td></tr>`).join('')}</tbody></table></div><div class="file-note">Изменения задач и журнала автоматически сохраняются в CSV. Импорт заменяет выбранную таблицу после проверки; остальные файлы сохраняются.</div></section>`;}
function audit(){const names={dashboard:'Изменён дашборд',create:'Создано решение',status:'Изменён статус',verify:'Проверен результат',sync:'Обмен данными',denied:'Отказ в доступе',signal:'Обнаружен сигнал',session:'Демо-сессия',integration:'Настройка источника'};const rows=data.audit.filter(e=>`${e.actorName} ${e.object} ${e.result}`.toLowerCase().includes(auditQuery.toLowerCase()));return pageHead('Журнал событий','История операций',canManage()?`<button class="btn" data-action="export">${icon('download')}Экспорт журнала</button>`:'')+`<div class="toolbar"><span class="status-meta"><i class="dot"></i>${data.audit.length} записей · время ${Intl.DateTimeFormat().resolvedOptions().timeZone}</span><input class="filter-input" id="audit-search" value="${esc(auditQuery)}" placeholder="Поиск по пользователю или объекту" aria-label="Поиск в журнале"></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>Время</th><th>Пользователь / источник</th><th>Действие</th><th>Объект</th><th>Результат</th></tr></thead><tbody>${rows.map(e=>`<tr><td class="audit-time">${date(e.at,true)}</td><td>${esc(e.actorName)}</td><td class="audit-action">${names[e.action]||esc(e.action)}</td><td>${pill(e.object)}</td><td class="audit-result ${e.success?'':'audit-failure'}"><span class="result-marker ${e.success?'':'failed'}"></span>${esc(e.result)}</td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('Записей не найдено','Попробуйте другой поисковый запрос.'):''}</section>`;}
function dictionary(){return pageHead('Словарь KPI','Формулы и источники. '+data.kpis.length+' рассчитываемых KPI.',secureAuth&&canManage()?'<button class="btn btn-primary" data-action="metric-new">'+icon('plus')+'Новая метрика</button>':'')+`<div class="dictionary-grid">${data.kpis.map(k=>`<section class="panel dictionary-card"><div class="dictionary-title"><h2>${icon(k.icon)}${k.label}</h2>${pill(k.state,k.trend==='negative'?'warning':'good')}</div><dl><dt>Формула · УП-02</dt><dd class="formula-inline">${esc(k.formula)}</dd><dt>Источник</dt><dd>${esc(k.source)} · ${date(k.sourceAt||data.lastUpdated,true)}</dd><dt>Владелец</dt><dd>${k.owner}</dd><dt>План / факт</dt><dd>${k.plan} / ${k.value}${k.unit}</dd><dt>Прогноз</dt><dd>${k.forecast}${k.unit}</dd></dl><div class="dictionary-actions"><button class="btn" data-action="metric" data-id="${k.id}">${icon('chart')}Исследовать</button><button class="btn ${data.dashboard.metrics.includes(k.id)?'selected':''}" data-action="dashboard-toggle" data-id="${k.id}">${icon(data.dashboard.metrics.includes(k.id)?'check':'plus')}${data.dashboard.metrics.includes(k.id)?'На дашборде':'На дашборд'}</button></div></section>`).join('')}</div>`;}

const formDrafts=new Map();
function draftKey(form){return 'contour-draft:'+data?.actor.id+':'+form.id+':'+(form.dataset.draftId||form.elements.signalId?.value||form.dataset.id||form.elements.id?.value||'new');}
function saveFormDraft(form){if(!form||form.dataset.saved==='true'||!form.dataset.changed)return;const key=draftKey(form),values={...Object.fromEntries(new FormData(form)),_key:pendingKey};formDrafts.set(key,values);try{sessionStorage.setItem(key,JSON.stringify(values));form.dataset.durable='true';}catch{form.dataset.durable='false';}}
function clearFormDraft(form){form.dataset.saved='true';const key=draftKey(form);formDrafts.delete(key);try{sessionStorage.removeItem(key);}catch{}}
function restoreFormDraft(form){let values=formDrafts.get(draftKey(form));try{values??=JSON.parse(sessionStorage.getItem(draftKey(form))||'null');}catch{}if(values){for(const [name,value] of Object.entries(values)){const input=form.elements.namedItem(name);if(input&&name!=='signalId')input.value=value;}pendingKey=values._key||pendingKey;form.dataset.changed='true';const note=document.createElement('p');note.className='draft-notice';note.textContent='Восстановлен несохранённый черновик. Проверьте срок и поля перед сохранением.';form.prepend(note);}}
function showDialog(content,drawer=false){closeDialog();document.querySelector('#overlay').innerHTML=`<dialog class="${drawer?'modal detail-modal':'modal'}" aria-label="${drawer?'Детали объекта':'Диалог'}">${content}</dialog>`;const dialog=document.querySelector('dialog');
 for(const form of dialog.querySelectorAll('#task-form,#complete-form,#verify-form,#metric-config-form')){restoreFormDraft(form);for(const event of ['input','change'])form.addEventListener(event,()=>{form.dataset.changed='true';saveFormDraft(form);});}
 dialog.showModal();enhanceSelects(dialog);hideReadonlyControls();dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeDialog();}});dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog();});return dialog;}
function closeDialog(){closeSelectMenu();const dialog=document.querySelector('dialog');for(const form of dialog?.querySelectorAll?.('#task-form,#complete-form,#verify-form,#metric-config-form')||[]){saveFormDraft(form);if(form.dataset.changed&&form.dataset.saved!=='true')toast('Черновик сохранён. Откройте форму, чтобы продолжить.');}dialog?.close();document.querySelector('#overlay').innerHTML='';currentOverlay=null;}
window.addEventListener('beforeunload',e=>{const forms=document.querySelectorAll('form[data-changed="true"]:not([data-saved="true"])');for(const form of forms){saveFormDraft(form);if(form.dataset.durable!=='true'){e.preventDefault();e.returnValue='Есть несохранённые изменения';}}});

function dialogHeader(title,subtitle='',tags=''){return `<header class="modal-header"><div>${tags}<h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="icon-button" data-action="close" aria-label="Закрыть">${icon('close')}</button></header>`;}
function openSignal(id){const s=data.signals.find(s=>s.id===id);if(!s)return;const t=data.tasks.find(t=>t.signalId===id&&t.status!=='done');showDialog(dialogHeader(s.title,s.description,pill(s.severity==='critical'?'Высокий приоритет':'Требует внимания',s.severity)+' '+pill(s.id))+`<div class="drawer-body"><section class="detail-section"><div class="detail-label"><span class="step-number">01</span>Сигнал и влияние</div><div class="detail-stat-row"><div class="detail-stat warning"><span>Зафиксировано</span><strong>${fmt(s.value)} <small>${s.unit}</small></strong></div><div class="detail-stat"><span>Целевое значение</span><strong>${s.metric==='moderation'?'≤':'≥'} ${s.target}</strong></div><div class="detail-stat"><span>Источник</span><strong>${sourceNames[s.source]}</strong></div></div></section><section class="detail-section"><div class="detail-label"><span class="step-number">02</span>Контекст</div><div class="context-box"><h3>Затронут заказ ${s.orderId}</h3><p>Сигнал сохранён на момент обнаружения; это основание решения, а не текущий агрегат KPI.<br>Владелец процесса: ${owner(s.owner).name}<br>Обнаружено: ${date(s.createdAt,true)}</p><button class="btn-link" style="margin-top:12px" data-action="order" data-id="${s.orderId}">Открыть сквозной путь${icon('arrow')}</button></div></section><section class="detail-section"><div class="detail-label"><span class="step-number">03</span>Причина отклонения</div><h3>${s.metric==='moderation'?'Не хватает ресурса на проверке':s.metric==='support'?'Неравномерная нагрузка поддержки':'Отмена рейса перевозчика'}</h3><p>${s.cause}</p><div class="evidence">${icon('info')} ${s.evidence}<br>Основание: ${s.sourceEventId} · ${date(s.createdAt,true)}</div></section><section class="detail-section"><div class="detail-label"><span class="step-number">04</span>Предлагаемое действие</div><div class="context-box"><p>${s.suggestion}</p></div></section><section class="detail-section"><div class="detail-label"><span class="step-number">05</span>Повторная проверка</div><p>После выполнения решения источник повторно вернёт значение показателя. Решение закроется только при достижении цели.</p></section></div><footer class="drawer-footer"><span>${ownerInline(s.owner)}</span>${t?`<button class="btn btn-dark" data-action="task" data-id="${t.id}">Решение ${t.id}${icon('arrow')}</button>`:s.status==='resolved'?pill('Результат проверен','good',true):canManage()?`<button class="btn btn-primary" data-action="create-task" data-id="${s.id}">${icon('plus')}Назначить решение</button>`:pill('Назначает руководитель')}</footer>`,true);currentOverlay={type:'signal',id};}
function openOrder(id,record=null){const o=record||data.orders.find(o=>o.id===id);if(!o)return;let events=o.events?.length?o.events:data.stages.map((name,i)=>({name,status:i<o.stage?'completed':i===o.stage?'active':'pending',owner:o.owner,source:'filesystem',at:null,result:i<o.stage?'Предшествующий этап по текущему статусу; время события не предоставлено.':null}));showDialog(dialogHeader('Заказ '+o.id,o.product,pill(o.status,'blue')+' '+pill(o.payment,o.payment==='Оплачен'?'good':'warning'))+`<div class="drawer-body"><section class="detail-section"><div class="detail-label">Единый контекст</div><div class="context-box"><p>${esc(o.client)}<br>Идентификатор клиента: ${esc(o.customerId||'CUS-DEMO-'+o.id)}<br>Рынок: ${o.market==='BY'?'Беларусь':o.market==='RU'?'Россия':'Не указан'} · ${esc(o.regionName||o.regionId||'')}<br>Владелец: ${owner(o.owner).name}</p></div></section>${orderReviews(o)}<div class="detail-label">${o.events?.length?'Сохранённые события':'Схема этапов по текущему статусу — не журнал событий'}</div>${o.promisedAt?`<p>Обещанный срок: ${date(o.promisedAt,true)} · завершён: ${o.completedAt?date(o.completedAt,true):'ещё не завершён'}</p>`:''}<div class="timeline">${events.map((e,i)=>`<section class="timeline-step"><span class="timeline-marker ${e.status==='completed'?'done':e.status==='active'?'active':''}">${e.status==='completed'?icon('check'):i+1}</span><h3>${e.name}</h3><p>${e.result|| (e.status==='active'?'Сейчас на этом этапе':'Ожидает предыдущего этапа')}</p><div class="timeline-meta">${sourceNames[e.source]||'ERP'} · ${owner(e.owner).name} ${e.at?'· '+date(e.at,true):''}</div></section>`).join('')}</div></div><footer class="drawer-footer"><span>Filesystem · ${o.events?.length?'сохранённая история':'текущий статус без выдуманных времён'}</span><button class="btn" data-action="close">Закрыть</button></footer>`,true);currentOverlay={type:'order',id};}
function metricSourceDetails(k){
 const source=k.sourceInfo;
 return `<section class="metric-provenance" aria-label="Источник метрики"><h4>${icon('plug')}Источник: ${esc(source?.name||'Filesystem')}</h4><dl><dt>Данные</dt><dd>${esc(source?.dataset||k.source)}</dd>${source?`<dt>Исходный набор</dt><dd>${esc(source.upstream)}</dd><dt>Статус</dt><dd>${source.status==='ok'?'Подключён':'Недоступен'}</dd>${source.queriedAt?`<dt>Получено из Metabase</dt><dd>${date(source.queriedAt,true)}</dd>`:''}${source.snapshotAt?`<dt>Снимок данных</dt><dd>${date(source.snapshotAt,true)}</dd>`:''}`:''}<dt>Обновление набора данных</dt><dd>${date(k.sourceAt,true)}</dd></dl>${k.sourceError?`<p role="status" class="source-error">${esc(k.sourceError)}</p>`:''}${source?'<p>Факт, история и разрезы рассчитаны в Metabase. План и сценарий — по правилам приложения.</p>':''}</section>`;
}
function openMetric(id){const k=metric(id);if(!k)return;const signal=data.signals.find(s=>s.metric===id&&s.status!=='resolved');showDialog(dialogHeader(k.label,'Исследование показателя · '+data.filters.from+' — '+data.filters.to,pill(k.state,k.trend==='negative'?'warning':'good'))+`<div class="metric-explorer"><div class="explorer-filters">${periodControl('metric-')}${filters('metric-')}</div><div class="explorer-summary"><div class="explorer-main"><span>Факт за период</span><strong>${k.value}<small>${esc(k.unit)}</small></strong></div>${[['План / цель',k.plan],['Предыдущий период',k.previous],['Изменение',k.delta===null?null:fmt(k.delta)+(k.unit==='%'?' п.п.':'')],['Сценарий',k.forecast]].map(([l,v])=>`<div><span>${l}</span><strong>${displayValue(v)}</strong></div>`).join('')}</div><section class="formula-block"><div><span class="eyebrow">ФОРМУЛА · УП-02</span><h3>${esc(k.formula)}</h3></div><div class="formula-meta"><span>${icon('plug')}${esc(k.source)}</span><span>${icon('clock')}${k.sourceTimes?.length?k.sourceTimes.map(s=>esc(s.file)+' · '+date(s.updatedAt,true)).join(' / '):'Обновлено '+date(k.sourceAt,true)}</span><span>${icon('users')}${esc(k.owner)}</span><span>Выборка: ${displayValue(k.sampleSize)}</span></div>${metricSourceDetails(k)}${k.scopeNote?`<p>${esc(k.scopeNote)}</p>`:''}</section><div class="explorer-chart-head"><h3>Динамика показателя</h3><div class="segmented">${[['period','По интервалам'],['cumulative','Накопительно'],['compare','Сравнение']].map(([v,l])=>`<button data-action="metric-view" data-id="${v}" class="${metricView===v?'active':''}">${l}</button>`).join('')}</div></div>${metricDetailChart(k)}${k.distribution?distributionPanel(k.distribution,k.id==='leadTime'?'ч':'мин'):''}<div class="explorer-bottom"><section><div class="section-head"><h3>Разрез показателя</h3><label><span class="sr-only">Группировка KPI</span><select id="metric-dimension"><option value="market" ${metricDimension==='market'?'selected':''}>По рынкам</option><option value="department" ${metricDimension==='department'?'selected':''}>По направлениям</option><option value="channel" ${metricDimension==='channel'?'selected':''}>По каналам</option></select></label></div>${metricBreakdown(k)}</section><section class="metric-context"><h3>${signal?'Отклонение и действие':'Связанные записи'}</h3>${signal?`<p>${esc(signal.cause)}</p><button class="btn btn-primary" data-action="signal" data-id="${signal.id}">Открыть причину ${icon('arrow')}</button>`:`<p>${data.totals.orders} заказов · ${data.totals.tickets} обращений · ${data.totals.reviews} отзывов в выбранном срезе.</p>`}<div class="related-orders">${data.orders.slice(0,4).map(o=>`<button data-action="order" data-id="${o.id}">${o.id}<span>${esc(o.status)}</span>${icon('right')}</button>`).join('')}</div><button class="btn-link" data-action="navigate" data-id="flow">Все заказы выбранного среза${icon('arrow')}</button></section></div></div><footer class="drawer-footer"><span>${k.snapshot?'Текущий снимок персонала; календарь смен доступен в производстве':esc(k.forecastMethod)}</span>${secureAuth&&k.custom&&canManage()?`<button class="btn" data-action="metric-update" data-id="${k.id}">Изменить</button><button class="btn" data-action="config-history" data-resource="metric/${k.id}">Версии</button>`:''}<button class="btn" data-action="dashboard-toggle" data-id="${k.id}">${icon(data.dashboard.metrics.includes(k.id)?'check':'plus')}${data.dashboard.metrics.includes(k.id)?'Убрать с дашборда':'На дашборд'}</button></footer>`,true);currentOverlay={type:'metric',id};}


function createTask(signalId){const s=data.signals.find(s=>s.id===signalId);const due=new Date(Date.now()+4*3600000);const localDue=new Date(due.getTime()-due.getTimezoneOffset()*60000).toISOString().slice(0,16);pendingKey=key();showDialog(dialogHeader('Новое решение',s?'На основании '+s.id+' · '+s.title:'Действие с владельцем, сроком и проверяемым результатом')+`<form id="task-form"><div class="modal-body"><div id="form-error"></div><input type="hidden" name="signalId" value="${s?.id||''}"><label class="form-field"><span>Проблема *</span><input name="problem" required minlength="5" maxlength="500" value="${esc(s?.title||'')}" placeholder="Какое отклонение нужно устранить?"></label><label class="form-field"><span>Причина *</span><textarea name="cause" required minlength="5" maxlength="500" placeholder="Укажите известную причину или напишите, что требует уточнения">${esc(s?.cause||'')}</textarea></label><label class="form-field"><span>Действие *</span><input name="title" required minlength="5" maxlength="160" value="${esc(s?s.suggestion:'')}" placeholder="Что нужно сделать?"></label><label class="form-field"><span>Контекст и ожидаемый результат</span><textarea name="description" maxlength="1200" placeholder="Как поймём, что проблема решена?">${esc(s?`Цель: ${s.metric==='moderation'?'очередь ≤':'показатель ≥'} ${s.target} ${s.unit}. ${s.cause}`:'')}</textarea></label><label class="form-field"><span>Влияние на бизнес *</span><input name="impact" required minlength="5" maxlength="500" value="${esc(s?s.description:'')}" placeholder="Какие заказы, клиенты или сроки затронуты?"></label><div class="form-row"><label class="form-field"><span>Владелец *</span><select name="owner" required>${data.owners.filter(o=>o.assignable&&(!s||o.departments.includes(s.department))).map(o=>`<option value="${o.id}" ${o.id===(s?.owner||'mikhail')?'selected':''}>${o.name}</option>`).join('')}</select></label><label class="form-field"><span>Срок *</span><input name="dueAt" type="datetime-local" required value="${localDue}"></label></div><label class="form-field"><span>Приоритет</span><select name="priority"><option value="high" ${s?.severity==='critical'?'selected':''}>Высокий</option><option value="medium" ${s?.severity!=='critical'?'selected':''}>Средний</option><option value="low">Низкий</option></select></label><div class="field-help">Часовой пояс: ${Intl.DateTimeFormat().resolvedOptions().timeZone}. Решение и запись аудита сохранятся на сервере.</div></div><footer class="form-actions"><button class="btn" type="button" data-action="close">Отмена</button><button class="btn btn-primary" type="submit">${icon('check')}Сохранить решение</button></footer></form>`);currentOverlay={type:'create-task',id:signalId};}
function openTask(id){const t=data.tasks.find(t=>t.id===id);if(!t)return;const s=data.signals.find(s=>s.id===t.signalId);const checks=data.checks.filter(c=>c.taskId===id);const history=data.audit.filter(e=>e.object===id);showDialog(dialogHeader(t.title,t.id+' · создано '+date(t.createdAt,true),pill(statusNames[t.status],t.status==='done'?'good':t.status==='review'?'warning':'blue')+' '+pill({high:'Высокий приоритет',medium:'Средний приоритет',low:'Низкий приоритет'}[t.priority]||'Плановое решение'))+`<div class="drawer-body"><section class="detail-section"><div class="detail-label">Владелец и срок</div><div class="context-box">${ownerInline(t.owner)}<p style="margin-top:12px">Срок: ${date(t.dueAt,true)}<br>Влияние: ${esc(t.impact||'Требует уточнения')}</p></div></section>${!s?`<section class="detail-section"><div class="detail-label">Проблема и причина</div><h3>${esc(t.problem||'Требует уточнения')}</h3><p>${esc(t.cause||'Требует уточнения')}</p></section>`:''}${s?`<section class="detail-section"><div class="detail-label">Проблема и причина</div><h3>${esc(t.problem||s.title)}</h3><p>${esc(t.cause||s.cause)}</p><button class="btn-link" style="margin-top:10px" data-action="signal" data-id="${s.id}">Основание ${s.id}${icon('arrow')}</button></section>`:''}<section class="detail-section"><div class="detail-label">Действие и ожидаемый результат</div><p>${esc(t.description||t.title)}</p></section>${t.result?`<section class="detail-section"><div class="detail-label">Результат действия</div><div class="context-box"><p>${esc(t.result)}</p></div></section>`:''}${checks.length?`<section class="detail-section"><div class="detail-label">Повторные проверки</div>${checks.map(c=>`<div class="verification-card ${c.passed?'':'failed'}"><strong>${icon(c.passed?'check':'alert')}${c.passed?'Цель достигнута':'Отклонение сохраняется'}</strong><p>${esc(c.evidence)}</p><small>${sourceNames[c.source]||'Ручная проверка'} · mock · ${date(c.at,true)}</small></div>`).join('')}</section>`:''}<section class="detail-section"><div class="detail-label">История решения</div>${history.map(e=>`<div class="evidence" style="margin-bottom:12px">${esc(e.result)}<br>${esc(e.actorName)} · ${date(e.at,true)}</div>`).join('')||'<p>История доступна в едином журнале событий.</p>'}</section></div><footer class="drawer-footer"><span>${t.status==='done'?'Результат сохранён и проверен':'Закрытие — после проверки результата'}</span>${t.status==='new'&&data.actor.role!=='analyst'?`<button class="btn btn-primary" data-action="task-start" data-id="${id}">Взять в работу${icon('arrow')}</button>`:t.status==='in_progress'&&data.actor.role!=='analyst'?`<button class="btn btn-primary" data-action="task-complete" data-id="${id}">Действие выполнено${icon('check')}</button>`:t.status==='review'&&canManage()?`<button class="btn btn-primary" data-action="verify-task" data-id="${id}">Проверить результат${icon('refresh')}</button>`:pill(statusNames[t.status],t.status==='done'?'good':'warning')}</footer>`,true);currentOverlay={type:'task',id};}
function completeTask(id){pendingKey=key();showDialog(dialogHeader('Зафиксировать действие','Опишите, что выполнено. Затем результат можно проверить повторно.')+`<form id="complete-form" data-id="${id}"><div class="modal-body"><div id="form-error"></div><label class="form-field"><span>Что сделано *</span><textarea name="note" required minlength="5" maxlength="1200" placeholder="Например: два сотрудника переведены на модерацию, очередь разобрана."></textarea></label></div><footer class="form-actions"><button type="button" class="btn" data-action="task" data-id="${id}">Назад</button><button type="submit" class="btn btn-primary">Передать на проверку</button></footer></form>`);}
function verifyTask(id){const t=data.tasks.find(t=>t.id===id);pendingKey=key();showDialog(dialogHeader('Повторная проверка','Будет сохранён новый ответ источника, его время и сравнение с целью.')+`<form id="verify-form" data-id="${id}"><div class="modal-body"><div id="form-error"></div><div class="snapshot-info">${icon('info')}Демосценарий · результат изменит данные Filesystem</div><label class="form-field"><span>Сценарий проверки</span><select name="scenario"><option value="recovered">Показатель восстановился — цель достигнута</option><option value="unchanged">Отклонение осталось — оставить на контроле</option></select></label>${!t.signalId?'<label class="form-field"><span>Проверяемый результат *</span><textarea name="note" required minlength="5" placeholder="Как и кем подтверждён результат?"></textarea></label>':''}<div class="field-help">При сохранении отклонения решение останется на проверке. Повтор запроса не создаёт вторую запись.</div></div><footer class="form-actions"><button type="button" class="btn" data-action="task" data-id="${id}">Назад</button><button type="submit" class="btn btn-primary">${icon('refresh')}Получить и проверить</button></footer></form>`);}
function openSearch(){showDialog(`<div class="search-input-wrap">${icon('search')}<input id="global-search" autofocus placeholder="Сигнал, заказ, решение…" aria-label="Поиск по контуру"><button class="icon-button" data-action="close" aria-label="Закрыть поиск">${icon('close')}</button></div><div class="search-results" id="search-results"><div class="search-hint">Начните вводить название или номер объекта</div></div>`);document.querySelector('dialog').classList.add('search-modal');}
function searchResults(query){const q=query.toLowerCase().trim();const items=[...data.signals.map(s=>({id:s.id,title:s.title,sub:'Сигнал · '+s.id,type:'signal',icon:'alert'})),...data.tasks.map(t=>({id:t.id,title:t.title,sub:'Решение · '+t.id,type:'task',icon:'decisions'})),...data.orders.map(o=>({id:o.id,title:o.id+' · '+o.product,sub:esc(o.client),type:'order',icon:'box'}))].filter(i=>q&&`${i.title} ${i.id} ${i.sub}`.toLowerCase().includes(q)).slice(0,12);document.querySelector('#search-results').innerHTML=items.map(i=>`<button class="search-result" data-action="${i.type}" data-id="${i.id}">${icon(i.icon)}<span><strong>${esc(i.title)}</strong><small>${esc(i.sub)}</small></span>${icon('arrow')}</button>`).join('')||`<div class="search-hint">${q?'Ничего не найдено в доступных данных':'Начните вводить название или номер объекта'}</div>`;}
function navigate(id){closeDialog();mobile=false;location.hash=id;if(page===id)render();}
async function changeRole(role){try{page='overview';history.replaceState(null,'','#overview');await api('/api/session',{method:'POST',body:{role}});localStorage.setItem('contour-role',role);department='all';product='all';employeeId='all';closeDialog();await load();toast('Демороль изменена. Права применены на сервере.');}catch(e){toast(e.message,true);render();}}
async function exportData(){try{const result=await api('/api/export?'+params());const blob=new Blob([JSON.stringify(page==='audit'?{exportedAt:result.exportedAt,audit:result.audit}:result,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='fotoprint-'+page+'-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Отчёт выгружен в JSON.');}catch(e){toast(e.message,true);}}

document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;
 const action=b.dataset.action,id=b.dataset.id;
 try{
  switch(action){
   case 'theme':{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('contour-theme',theme);}catch{}document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#101c20':'#edf3f5';render();break;}
   case 'reload':return init();case 'menu':mobile=!mobile;render();document.querySelector(mobile?'.sidebar .nav-link':'[data-action="menu"]')?.focus();break;case 'close':closeDialog();break;case 'search':openSearch();break;
   case 'navigate':navigate(id);break;case 'metric':metricView='period';openMetric(id);break;case 'signal':openSignal(id);break;case 'order':await openOrderById(id);break;case 'task':openTask(id);break;case 'create-task':createTask(id);break;case 'task-complete':completeTask(id);break;case 'verify-task':verifyTask(id);break;
   case 'chart':chartTab=id;render();break;case 'task-filter':taskFilter=id;render();break;case 'stage':flowStage=id;flowPage=0;render();break;case 'flow-page':flowPage=Number(id);render();break;
   case 'signals':if(page==='overview'){document.querySelector('#signals-section')?.scrollIntoView({behavior:'smooth',block:'center'});if(activeSignals().length)openSignal(activeSignals()[0].id);}else if(activeSignals().length)openSignal(activeSignals()[0].id);else navigate('decisions');break;
   case 'health-info':showDialog(dialogHeader('Как устроен индекс здоровья','Прозрачное правило без скрытых весов')+`<div class="modal-body"><p style="font-size:12px;line-height:1.9;color:#7c8b9d">Индекс = 100 − 2 × число KPI со статусом «Требует внимания».<br><br>Клиентский контур: демонстрационный эталон 98%. Производственный контур: 100 − 12 × открытые сигналы фотокниг. Сервис: среднее SLA поддержки и доставки в срок.<br><br>Показатель предназначен для обзора. Детальные формулы доступны в словаре KPI.</p></div>`);break;
   case 'refresh':if(refreshing)return;refreshing=true;b.disabled=true;await load();refreshing=false;toast('Витрина обновлена из сохранённых данных источников.');break;
   case 'export':await exportData();break;
   case 'file-download':await downloadFile(id);break;
   case 'file-confirm':if(!pendingImport)return;b.disabled=true;try{const r=await api('/api/files/'+encodeURIComponent(pendingImport.name),{method:'POST',body:{csv:pendingImport.csv}});pendingImport=null;closeDialog();await load();toast('Импортировано '+r.rows+' записей. Дашборд пересчитан.');}catch(err){document.querySelector('#form-error').innerHTML=`<div class="form-error">${esc(err.message)}</div>`;b.disabled=false;}break;
   case 'task-start':b.disabled=true;await api(`/api/tasks/${id}/status`,{method:'PATCH',body:{status:'in_progress'}});await load();openTask(id);toast('Решение взято в работу.');break;
   case 'sync':b.disabled=true;try{const result=await api(`/api/integrations/${id}/sync`,{method:'POST',body:{}});await load();toast(result.duplicate?'Повтор события обработан без дубликата.':'Источник синхронизирован.');}catch(err){await load();throw err;}break;
  }
 }catch(err){refreshing=false;if(b.isConnected)b.disabled=false;toast(err.message,true);}
});
document.addEventListener('change',async e=>{
 const el=e.target;
 if(el.dataset.import){const file=el.files[0];if(!file)return;if(file.size>1800000){toast('Максимальный размер CSV — 1,8 МБ',true);el.value='';return;}previewImport(el.dataset.import,file,await file.text());el.value='';return;}
 if(el.id==='role-select')return changeRole(el.value);
 if(el.dataset.filter)return applyFilter(el.dataset.filter,el.value);
 if(['period-filter','department-filter','product-filter'].includes(el.id)){
  const before={period,department,product};if(el.id==='period-filter')period=el.value;if(el.id==='department-filter'){department=el.value;product='all';}if(el.id==='product-filter')product=el.value;flowPage=0;
  try{await load();}catch(err){({period,department,product}=before);render();toast(err.message,true);}
 }
 if(el.dataset.failure){el.disabled=true;try{await api(`/api/integrations/${el.dataset.failure}/failure`,{method:'POST',body:{enabled:el.checked}});await load();toast(el.checked?'Тест сбоя включён. Прогресс сохранён.':'Mock-источник восстановлен.');}catch(err){toast(err.message,true);render();}}
});
let searchTimer;
document.addEventListener('input',e=>{
 const el=e.target;if(el.id==='global-search')return searchResults(el.value);
 if(['flow-search','audit-search','task-search'].includes(el.id)){
  const value=el.value,pos=el.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(el.id==='flow-search'){flowQuery=value;flowPage=0;}if(el.id==='audit-search')auditQuery=value;if(el.id==='task-search')taskQuery=value;render();const next=document.getElementById(el.id);next?.focus();next?.setSelectionRange(pos,pos);},150);
 }
});
document.addEventListener('submit',async e=>{
 const form=e.target;
 if(form.hasAttribute('data-date-range')){e.preventDefault();const v=Object.fromEntries(new FormData(form));return applyDateRange(v.from,v.to);}
if(!['task-form','complete-form','verify-form'].includes(form.id))return;e.preventDefault();
 const submit=form.querySelector('[type="submit"]');if(submit.disabled)return;submit.disabled=true;const values=Object.fromEntries(new FormData(form));
 try{
  let result;
  if(form.id==='task-form'){values.dueAt=new Date(values.dueAt).toISOString();result=await api('/api/tasks',{method:'POST',body:values,key:pendingKey});clearFormDraft(form);closeDialog();await load();page='decisions';history.replaceState(null,'','#decisions');render();toast('Решение '+result.task.id+' сохранено. Владелец и срок назначены.');openTask(result.task.id);}
  if(form.id==='complete-form'){result=await api(`/api/tasks/${form.dataset.id}/status`,{method:'PATCH',body:{status:'review',note:values.note},key:pendingKey});clearFormDraft(form);await load();openTask(result.task.id);toast('Действие сохранено. Теперь проверьте результат.');}
  if(form.id==='verify-form'){result=await api(`/api/tasks/${form.dataset.id}/verify`,{method:'POST',body:values,key:pendingKey});clearFormDraft(form);await load();openTask(result.task.id);toast(result.check.passed?'Цель достигнута. Решение проверено и закрыто.':'Проверка сохранена. Отклонение осталось на контроле.',!result.check.passed);}
 }catch(err){const target=document.querySelector('#form-error');if(target)target.innerHTML=`<div class="form-error" role="alert">${esc(err.message)} Введённые данные сохранены в форме.</div>`;else toast(err.message,true);if(submit.isConnected)submit.disabled=false;}
});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(data)openSearch();}if(e.key==='Enter'&&e.target.matches('tr[data-action]')){e.preventDefault();e.target.click();}if(e.key==='Escape'&&mobile){mobile=false;render();document.querySelector('[data-action="menu"]')?.focus();}});
window.addEventListener('hashchange',()=>{page=pageNames[location.hash.slice(1)]?location.hash.slice(1):'overview';closeDialog();mobile=false;if(data)render();window.scrollTo(0,0);});
init();

const fileLabels={'finance_entries.csv':'Финансовые планы, факты и сверка ERP / 1С','reviews.csv':'Отзывы, связанные с заказами','responses.csv':'События ответов менеджеров и ботов','employees.csv':'Сотрудники и направления','dashboard_layouts.csv':'Сохранённые дашборды','orders.csv':'Заказы и финансовые показатели','customers.csv':'Клиенты','interactions.csv':'Обращения и SLA','staff.csv':'Команда и мощности','performance.csv':'Эффективность менеджеров и Mary','process_orders.csv':'Этапы и история заказов','signals.csv':'Отклонения и сигналы','tasks.csv':'Решения и задачи','checks.csv':'Проверки результатов','audit.csv':'Журнал действий','adapters.csv':'Конфигурация адаптеров','schema.csv':'Колонки и типы полей','metadata.csv':'Версия и время обновления'};
async function downloadFile(name){const result=await api('/api/files/'+encodeURIComponent(name));const url=URL.createObjectURL(new Blob(['\ufeff'+result.csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let pendingImport=null;
function previewImport(name,file,csv){pendingImport={name,csv};showDialog(dialogHeader('Импорт '+name,'Таблица будет заменена содержимым выбранного файла.')+`<div class="modal-body"><div id="form-error"></div><div class="import-meta"><strong>${esc(file.name)}</strong><span>${fmt(file.size/1024)} КБ</span></div><pre class="csv-preview">${esc(csv.slice(0,1800))}</pre><p class="field-help">Сервер проверит колонки, значения, идентификаторы и связи. При ошибке текущие данные сохранятся.</p></div><footer class="form-actions"><button class="btn" data-action="close">Отмена</button><button class="btn btn-primary" data-action="file-confirm">Импортировать CSV</button></footer>`);}


const displayValue=v=>v===null||v===undefined?'—':typeof v==='number'?fmt(v):esc(v);
let activeSelect=null,selectSequence=0,filterBusy=false;
function closeSelectMenu(restore=false){if(!activeSelect)return;const {button,list}=activeSelect;try{list.hidePopover();}catch{}list.hidden=true;button.setAttribute('aria-expanded','false');activeSelect=null;if(restore)button.focus();}
function enhanceSelects(root=document){
 root.querySelectorAll('select:not([data-enhanced])').forEach(select=>{
  select.dataset.enhanced='true';const wrapper=document.createElement('div');wrapper.className='custom-select';select.before(wrapper);wrapper.append(select);select.hidden=true;select.tabIndex=-1;select.setAttribute('aria-hidden','true');
  const button=document.createElement('button'),list=document.createElement('div'),listId='select-options-'+(++selectSequence);
  button.type='button';button.className='select-trigger';button.setAttribute('role','combobox');button.setAttribute('aria-haspopup','listbox');button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls',listId);
  const label=select.getAttribute('aria-label')||select.closest('label')?.querySelector('span')?.textContent||({owner:'Владелец',priority:'Приоритет',scenario:'Сценарий'}[select.name])||'Выбор';
  const selected=()=>{button.innerHTML=`<span>${esc(select.selectedOptions[0]?.textContent||'Выберите')}</span>${icon('down')}`;button.setAttribute('aria-label',label+': '+(select.selectedOptions[0]?.textContent||''));};selected();
  list.id=listId;list.className='select-options';list.setAttribute('role','listbox');list.setAttribute('aria-label',label);list.setAttribute('popover','manual');list.hidden=true;
  let lastGroup='';for(const option of select.options){const group=option.parentElement.tagName==='OPTGROUP'?option.parentElement.label:'';if(group&&group!==lastGroup){const title=document.createElement('div');title.className='select-group';title.textContent=group;list.append(title);lastGroup=group;}
   const item=document.createElement('button');item.type='button';item.className='select-option';item.setAttribute('role','option');item.dataset.value=option.value;item.setAttribute('aria-selected',String(option.selected));item.innerHTML=`<span>${esc(option.textContent)}</span>${option.selected?icon('check'):''}`;item.disabled=option.disabled;item.addEventListener('click',()=>{select.value=option.value;selected();for(const row of list.querySelectorAll('[role="option"]')){const chosen=row.dataset.value===select.value;row.setAttribute('aria-selected',String(chosen));row.innerHTML=`<span>${esc([...select.options].find(o=>o.value===row.dataset.value)?.textContent||'')}</span>${chosen?icon('check'):''}`;}closeSelectMenu(true);select.dispatchEvent(new Event('change',{bubbles:true}));});list.append(item);
  }
  wrapper.append(button,list);
  const open=()=>{if(activeSelect?.button===button){closeSelectMenu(true);return;}closeSelectMenu();list.hidden=false;try{list.showPopover();}catch{}const r=button.getBoundingClientRect(),width=Math.min(innerWidth-24,Math.max(r.width,select.id==='role-select'?390:240));list.style.width=width+'px';list.style.left=Math.max(12,Math.min(r.left,innerWidth-width-12))+'px';list.style.top=Math.max(12,Math.min(r.bottom+7,innerHeight-Math.min(list.scrollHeight,320)-12))+'px';button.setAttribute('aria-expanded','true');activeSelect={button,list};(list.querySelector('[aria-selected="true"]')||list.querySelector('[role="option"]'))?.focus();};
  button.addEventListener('click',open);button.addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp','Enter',' '].includes(e.key)){e.preventDefault();open();}});
  let typed='',typeTimer;list.addEventListener('keydown',e=>{const items=[...list.querySelectorAll('[role="option"]:not(:disabled)')],i=items.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeSelectMenu(true);}else if(e.key==='Tab'){closeSelectMenu(true);}else if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();items[e.key==='Home'?0:e.key==='End'?items.length-1:(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus();}else if(e.key.length===1&&e.key!==' '){typed+=e.key.toLocaleLowerCase();clearTimeout(typeTimer);typeTimer=setTimeout(()=>typed='',600);items.find(o=>o.textContent.toLocaleLowerCase().startsWith(typed))?.focus();}});
 });
}
document.addEventListener('pointerdown',e=>{if(activeSelect&&!activeSelect.list.contains(e.target)&&!activeSelect.button.contains(e.target))closeSelectMenu();});
window.addEventListener('resize',()=>closeSelectMenu());
async function applyFilter(name,value){
 if(filterBusy)return;closeSelectMenu();const before={period,department,product,market,region,fromDate,toDate},overlay=currentOverlay;
 if(name==='period')period=value;if(name==='department'){department=value;product='all';employeeId='all';}if(name==='product')product=value;if(name==='market'){market=value;region='all';}if(name==='region')region=value;
 filterBusy=true;flowPage=0;
 try{await load();if(overlay?.type==='metric')openMetric(overlay.id);if(overlay?.type==='employee'){if([...data.employeeStats.people,...data.employeeStats.bots].some(e=>e.id===overlay.id))openEmployee(overlay.id);else closeDialog();}}
 catch(error){({period,department,product,market,region,fromDate,toDate}=before);render();toast(error.message,true);}finally{filterBusy=false;}
}
async function applyDateRange(from,to){if(!from||!to||from>to){toast('Укажите начало и конец периода в правильном порядке.',true);return;}const oldFrom=fromDate,oldTo=toDate;fromDate=from;toDate=to;await applyFilter('period','custom');if(data.filters.from!==from||data.filters.to!==to){fromDate=oldFrom;toDate=oldTo;render();}}
function metricDetailChart(k){
 if(k.sourceError)return empty('Источник недоступен',k.sourceError);
 if(k.value==='—')return empty('Нет данных в этом срезе','Измените период, рынок или продукт.');
 const actual=metricView==='cumulative'?k.cumulativeSeries:k.series,compare=metricView==='compare'?k.previousSeries:[],all=[...actual,...compare].filter(v=>v!==null),max=Math.max(1,...all)*1.15,min=Math.min(0,...all),x=i=>54+i*920/Math.max(1,actual.length-1),y=v=>238-(v-min)/(max-min)*206;
 const line=actual.map((v,i)=>v===null?null:[x(i),y(v)]),prior=compare.map((v,i)=>v===null?null:[x(i),y(v)]),labels=[...new Set([0,Math.floor((actual.length-1)/2),actual.length-1])];
 return `<section class="metric-detail-chart"><svg viewBox="0 0 1020 285" role="img" aria-label="${esc(k.label)}: ${metricView==='compare'?'сравнение с предыдущим периодом':metricView==='cumulative'?'накопительный расчёт':'по интервалам'}">${[0,.5,1].map(n=>`<line x1="54" x2="974" y1="${y(min+n*(max-min))}" y2="${y(min+n*(max-min))}" stroke="currentColor" stroke-opacity=".15" stroke-dasharray="4 6"/><text x="43" y="${y(min+n*(max-min))+4}" text-anchor="end">${fmt(min+n*(max-min))}</text>`).join('')}${prior.length?`<path d="${splitPlot(prior).map(curve).join(' ')}" fill="none" stroke="#b8a0ed" stroke-width="2" stroke-dasharray="6 6"/>`:''}<path d="${splitPlot(line).map(curve).join(' ')}" fill="none" stroke="#4acb9c" stroke-width="3"/>${line.map((p,i)=>p?`<circle cx="${p[0]}" cy="${p[1]}" r="3.5" fill="#4acb9c"><title>${esc(k.seriesLabels[i])}: ${fmt(actual[i])}${esc(k.unit)}</title></circle>`:'').join('')}${labels.map(i=>`<text x="${x(i)}" y="268" text-anchor="${i===0?'start':i===actual.length-1?'end':'middle'}">${esc(k.seriesLabels[i])}</text>`).join('')}</svg><div class="chart-legend"><span><i class="legend-line"></i>Выбранный период</span>${prior.length?'<span><i class="legend-line forecast"></i>Предыдущий равный период</span>':''}</div><p>${k.snapshot?'Снимок ресурса: исторические смены отсутствуют.':metricView==='cumulative'?'На каждой точке формула заново рассчитана от начала периода; проценты не суммируются.':'Каждая точка рассчитана отдельно за интервал; даты в Europe/Minsk.'}</p></section>`;
}
function distributionPanel(d,unit='мин'){return `<section class="distribution-panel"><div class="section-head"><div><h3>Распределение времени</h3><p>${d.n} наблюдений${d.n<20?' · малая выборка, перцентили нестабильны':''}</p></div>${pill('Не только среднее','blue')}</div><div class="distribution-grid">${[['Среднее',d.mean],['P50 · медиана',d.p50],['P90',d.p90],['P95',d.p95]].map(([l,v])=>`<div><span>${l}</span><strong>${displayValue(v)} <small>${unit}</small></strong></div>`).join('')}</div><p>90% наблюдений не превышают P90. Линейная интерполяция отсортированной выборки: h = (n − 1) × p.</p></section>`;}
function metricBreakdown(k){const rows=k.breakdowns[metricDimension]||[],max=Math.max(1,...rows.map(r=>Math.abs(r.value||0)));return `<div class="breakdown-list">${rows.map(r=>`<div><div><strong>${esc(r.name)}</strong><span>${displayValue(r.value)}${k.unit==='%'?'%':''}</span></div><div class="channel-bar"><i style="width:${Math.abs(r.value||0)/max*100}%"></i></div><small>${r.orders} заказов${r.tickets===undefined?'':` · ${r.tickets} обращений`}</small></div>`).join('')}</div>`;}
function geographyPanel(){
 const regions=data.geography||[],max=Math.max(1,...regions.map(r=>r.orders)),color=r=>!r.orders?'var(--map-empty)':`hsl(157 45% ${22+Math.sqrt(r.orders/max)*39}%)`;
 const maps=['BY','RU'].filter(m=>market==='all'||market===m).map(m=>{const rs=regions.filter(r=>r.market===m);if(!rs.length)return '';const total=rs.reduce((n,r)=>n+r.orders,0);return `<section class="country-map ${m==='BY'?'belarus':'russia'}"><div class="country-heading"><span class="country-code">${m==='BY'?'РБ':'РФ'}</span><div><h3>${m==='BY'?'Беларусь':'Россия'}</h3><span>${fmt(total)} заказов · ${rs.filter(r=>r.orders).length} регионов с заказами</span></div></div><svg viewBox="${rs[0].viewBox}" class="region-map" aria-label="Тепловая карта ${m==='BY'?'Беларуси':'России'} по числу заказов">${rs.map(r=>`<path d="${r.path}" fill="${color(r)}" class="map-region ${region===r.id?'selected':''}" data-action="region" data-id="${r.id}" data-map-region="true" role="button" tabindex="0" aria-label="${esc(r.name)}: ${r.orders} заказов. Фильтровать" fill-rule="evenodd"><title>${esc(r.name)}\n${r.orders} заказов · ${r.share}% выборки\nПредыдущий период: ${r.previous}</title></path>`).join('')}</svg></section>`;}).join('');
 const ranked=[...regions].sort((a,b)=>b.orders-a.orders).filter(r=>r.orders).slice(0,6);
 return `<section class="panel geography-panel"><div class="panel-header"><div><h2 class="panel-title">География продаж</h2><p class="panel-subtitle">Нажмите на регион, чтобы отфильтровать все связанные показатели</p></div><span class="pill good">${data.totals.orders} заказов</span></div><div class="geography-layout"><div class="maps ${market!=='all'?'single-map':''}">${maps}<div class="map-legend"><span><i class="no-data-swatch"></i>0 заказов</span><span>Меньше</span><i class="heat-gradient"></i><span>Больше · ${max}</span></div></div><aside class="region-ranking"><h3>Регионы по заказам</h3>${ranked.map((r,i)=>`<button data-action="region" data-id="${r.id}" class="${region===r.id?'active':''}"><span class="rank-index">${i+1}</span><span>${esc(r.name)}<small>${r.share}% · ${r.market==='BY'?'РБ':'РФ'}</small></span><strong>${r.orders}</strong></button>`).join('')||'<p>В выбранном периоде заказов нет.</p>'}<label><span class="field-caption">Выбрать любой регион</span><select data-filter="region" aria-label="Регион продаж"><option value="all">Все регионы</option>${regions.map(r=>`<option value="${r.id}" ${region===r.id?'selected':''}>${esc(r.name)} · ${r.orders}</option>`).join('')}</select></label></aside></div><div class="map-caption">Количество заказов, созданных за период · общая шкала цветов для двух рынков · <a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noreferrer">Natural Earth, public domain</a></div></section>`;
}
function orderReviews(o){return `<section class="detail-section order-reviews"><div class="detail-label">Отзывы к заказу · ${o.reviews?.length||0}</div>${o.reviews?.length?o.reviews.map(r=>`<article class="review-card"><div><strong class="review-stars" aria-label="Оценка ${r.rating} из 5">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</strong><span>${esc(r.topic)} · ${date(r.createdAt,true)}</span></div><p>${esc(r.text)}</p><small>${esc(r.id)} · ${esc(r.source)} · ${esc(r.orderId)}</small></article>`).join(''):'<div class="context-box"><p>Для этого заказа отзыв ещё не поступил.</p></div>'}</section>`;}
function reviewsPanel(){const rows=data.reviews||[];return `<section class="panel reviews-panel"><div class="panel-header"><div><h2 class="panel-title">Обратная связь клиентов</h2><p class="panel-subtitle">Отзывы, полученные за выбранный период · ${rows.length}</p></div><a class="btn-link" href="#flow">К заказам${icon('arrow')}</a></div><div class="review-grid">${rows.slice(0,4).map(r=>`<article class="review-card"><div><strong class="review-stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</strong><span>${esc(r.topic)}</span></div><p>${esc(r.text)}</p><button class="btn-link" data-action="review-order" data-id="${r.orderId}">${r.orderId}${icon('arrow')}</button><small>${date(r.createdAt,true)}</small></article>`).join('')||'<p>Нет отзывов в выбранном срезе.</p>'}</div></section>`;}
function staffOverview(){const s=data.employeeStats;if(!s)return '';return `<section class="panel staff-preview"><div><span class="eyebrow">КОМАНДА И СЕРВИС</span><h2>Эффективность сотрудников</h2><p>${s.people.length} сотрудников · ${data.totals.tickets} обращений · ${displayValue(s.summary.sla)}% в SLA</p></div><a class="btn" href="#employees">Открыть статистику${icon('arrow')}</a></section>`;}
function employees(){
 const s=data.employeeStats;if(!s)return empty('Раздел доступен руководителям');
 const selected=s.people.find(p=>p.id===employeeId)||s.bots.find(p=>p.id===employeeId),summary=selected||s.summary;
 return pageHead('Сотрудники','Нагрузка, скорость ответа и качество сервиса · '+data.actor.focus,standardActions())+filters()+`<div class="staff-toolbar"><span>${pill('SLA ≤ 15 мин','good')} ${data.filters.from} — ${data.filters.to}</span><label><span class="sr-only">Сотрудник</span><select id="employee-filter"><option value="all">Вся команда</option>${[...s.people,...s.bots].map(p=>`<option value="${p.id}" ${employeeId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div>${staffStats(summary)}<section class="panel staff-table"><div class="panel-header"><div><h2 class="panel-title">Рейтинг менеджеров${period==='today'?' за день':' за период'}</h2><p class="panel-subtitle">SLA → скорость ответа → объём обращений · боты учитываются отдельно</p></div><button class="btn" data-action="staff-today">Сегодня</button></div><div class="table-scroll"><table><thead><tr><th>Место / сотрудник</th><th>Обращения</th><th>Доля SLA</th><th>Средний ответ</th><th>P90</th><th>Ответы / в раб. время</th><th>Заказы</th><th></th></tr></thead><tbody>${s.people.filter(e=>employeeId==='all'||e.id===employeeId).map((e,i)=>`<tr><td><button class="employee-link" data-action="employee" data-id="${e.id}"><span class="rank-badge">${e.tickets?s.people.findIndex(p=>p.id===e.id)+1:'—'}</span><span class="avatar">${esc(e.name.split(' ').map(x=>x[0]).join(''))}</span><span><strong>${esc(e.name)}</strong><small>${esc(data.departments.find(d=>d.id===e.department)?.name||'')}</small></span></button></td><td>${e.tickets}</td><td>${pill(displayValue(e.sla)+(e.sla===null?'':'%'),e.sla===null?'':e.sla>=95?'good':'warning')}</td><td>${displayValue(e.response.mean)} мин</td><td>${displayValue(e.response.p90)} мин</td><td>${e.replies} / ${e.workingReplies}</td><td>${e.orders}</td><td><button class="icon-button" data-action="employee" data-id="${e.id}" aria-label="Статистика ${esc(e.name)}">${icon('right')}</button></td></tr>`).join('')}</tbody></table></div><p class="section-note">Сотрудники без обращений не ранжируются. Заказы — по назначенному менеджеру; ответы — по автору события. Рейтинг не является кадровым решением.</p></section><div class="staff-analysis">${topicPanel(summary)}${responseTypePanel(summary)}</div>${selected?distributionPanel(summary.response):dailyStaffPanel(s.daily)}<section class="panel bot-panel"><div class="panel-header"><div><h2 class="panel-title">Эффективность ботов</h2><p class="panel-subtitle">Самостоятельное решение и передача человеку</p></div>${pill('Отдельная выборка','blue')}</div><div class="bot-grid">${s.bots.filter(e=>employeeId==='all'||e.id===employeeId).map(b=>`<div class="bot-card"><div class="bot-name"><span class="mary-avatar">M</span><div><h3>${esc(b.name)}</h3><span>AI-менеджер</span></div><button class="btn" data-action="employee" data-id="${b.id}">Детали${icon('arrow')}</button></div><div class="bot-stats">${[['Обращения',b.tickets],['Решено без человека',b.autonomous],['Автономность',displayValue(b.autonomousShare)+'%'],['Передано человеку',b.handoffs]].map(([l,v])=>`<div><span>${l}</span><strong>${v}</strong></div>`).join('')}</div></div>`).join('')||'<p>Выбран сотрудник. Для статистики бота выберите «Вся команда».</p>'}</div></section><div class="info-panel">${icon('info')}<div>${esc(s.workSchedule)}<br>${esc(s.replyScope)}<br>Данные синтетические. Для процентов показан знаменатель; среднее и перцентили рассчитываются по отдельным обращениям.</div></div>`;
}
function staffStats(s){return `<div class="staff-stats">${[['Обращений',s.tickets],['Доля SLA',displayValue(s.sla)+(s.sla===null?'':'%')],['Средний ответ',displayValue(s.response.mean)+' мин'],['P90 ответа',displayValue(s.response.p90)+' мин'],['Ответов в рабочее время',s.workingReplies+' / '+s.replies],['Заказов в портфеле',s.orders]].map(([l,v])=>`<div class="panel"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div>`;}
function topicPanel(s){return `<section class="panel topic-panel"><div class="panel-header"><h2 class="panel-title">SLA по темам</h2></div><div class="table-scroll"><table><thead><tr><th>Тема</th><th>Обращения</th><th>SLA</th><th>P90, мин</th></tr></thead><tbody>${s.topics.map(t=>`<tr><td>${esc(t.topic)}</td><td>${t.count}</td><td>${displayValue(t.sla)}%</td><td>${displayValue(t.response.p90)}</td></tr>`).join('')||'<tr><td colspan="4">Нет обращений</td></tr>'}</tbody></table></div></section>`;}
function responseTypePanel(s){const labels={first_reply:'Первый ответ',clarification:'Уточнение',resolution:'Решение вопроса'};return `<section class="panel response-types"><div class="panel-header"><h2 class="panel-title">Какие ответы отправлены</h2></div><div class="channel-list">${s.types.map(t=>`<div class="channel"><div><strong>${labels[t.type]}</strong><span>${t.count}</span></div><div class="channel-bar"><i style="width:${s.replies?t.count/s.replies*100:0}%"></i></div></div>`).join('')}</div><div class="work-time-summary"><span>SLA в рабочее время</span><strong>${displayValue(s.workingSla)}%</strong><small>${s.workingTickets} обращений поступило в рабочие часы</small></div></section>`;}
function dailyStaffPanel(rows){return `<section class="panel daily-staff"><div class="panel-header"><div><h2 class="panel-title">Дневная статистика</h2><p class="panel-subtitle">Нажмите день для рейтинга менеджеров за эту дату</p></div></div><div class="table-scroll"><table><thead><tr><th>Дата</th><th>Обращения</th><th>SLA</th><th>Средний ответ</th><th>Ответы</th><th>Заказы</th></tr></thead><tbody>${rows.map(d=>`<tr><td><button class="btn-link" data-action="staff-day" data-id="${d.date}">${d.date}</button></td><td>${d.tickets}</td><td>${displayValue(d.sla)}%</td><td>${displayValue(d.response.mean)} мин</td><td>${d.replies}</td><td>${d.orders}</td></tr>`).join('')}</tbody></table></div></section>`;}
function openEmployee(id){const s=data.employeeStats,e=[...(s?.people||[]),...(s?.bots||[])].find(e=>e.id===id);if(!e)return;showDialog(dialogHeader(e.name,(e.isAgent?'AI-менеджер':'Сотрудник')+' · '+data.filters.from+' — '+data.filters.to)+`<div class="employee-detail"><div class="explorer-filters">${periodControl('employee-')}${filters('employee-')}</div>${staffStats(e)}${distributionPanel(e.response)}<div class="staff-analysis">${topicPanel(e)}${responseTypePanel(e)}</div><section class="formula-block"><span class="eyebrow">МЕТОДИКА И ИСТОЧНИК</span><p>SLA = обращения с первым ответом ≤ 15 минут / обращения менеджера × 100%. Среднее = сумма firstReplyMinutes / число обращений. Заказы = count(order.managerId). Ответы = count(response.employeeId).</p><p>${esc(s.workSchedule)}</p><div class="formula-meta">interactions.csv + responses.csv + orders.csv · обновлено ${date(data.source.updatedAt,true)}</div>${e.isAgent?`<p>Автономность = решено ботом без передачи человеку / обращения бота × 100% = ${e.autonomous} / ${e.tickets} → ${displayValue(e.autonomousShare)}%.</p>`:''}</section></div>`,true);currentOverlay={type:'employee',id};}
function openDashboardEditor(){dashboardDraft=[...data.dashboard.metrics];renderDashboardEditor();}
function renderDashboardEditor(){showDialog(dialogHeader('Настроить дашборд','Выберите метрики и порядок. Обязательные KPI закреплены. Сохранение — после предпросмотра.')+`<div class="dashboard-editor"><div><h3>Метрики на дашборде <span>${dashboardDraft.length}</span></h3><div class="selected-metrics">${dashboardDraft.map((id,i)=>`<div><span class="rank-index">${i+1}</span><strong>${esc(metric(id)?.label||id)}</strong><button type="button" class="icon-button" data-action="dashboard-move-up" data-id="${id}" ${i===0?'disabled':''} aria-label="Поднять ${esc(metric(id)?.label)}">↑</button><button type="button" class="icon-button" data-action="dashboard-move-down" data-id="${id}" ${i===dashboardDraft.length-1?'disabled':''} aria-label="Опустить ${esc(metric(id)?.label)}">↓</button><button type="button" class="icon-button" data-action="dashboard-remove" data-id="${id}" ${data.dashboard.required?.includes(id)?'disabled':''} aria-label="Убрать ${esc(metric(id)?.label)}">${icon('close')}</button></div>`).join('')||'<p>Добавьте хотя бы одну метрику из словаря.</p>'}</div></div><div><h3>Словарь KPI</h3><div class="metric-catalog">${data.kpis.map(k=>`<label><input type="checkbox" data-dashboard-metric="${k.id}" ${data.dashboard.required?.includes(k.id)?'disabled':''} ${dashboardDraft.includes(k.id)?'checked':''}><span><strong>${esc(k.label)}</strong><small>${esc(k.formula)}</small></span></label>`).join('')}</div></div></div><footer class="form-actions">${secureAuth?`<button class="btn" data-action="config-history" data-resource="layout/${data.dashboard.layoutId}">История версий</button>`:''}<button class="btn" data-action="dashboard-defaults">По умолчанию</button><button class="btn btn-primary" data-action="dashboard-save" ${!dashboardDraft.length?'disabled':''}>${icon('check')}Предпросмотр изменений</button></footer>`,true);currentOverlay={type:'dashboard'};}
async function saveDashboard(ids){if(!canManage())return toast('Изменения доступны руководителям.',true);if(secureAuth){const r=await api('/api/v1/proposals',{method:'POST',body:{kind:'layout',baseVersion:data.dashboard.version,layout:{id:data.dashboard.layoutId,metricIds:ids}}});return openProposal(r.proposal.id);}await api('/api/dashboard',{method:'POST',body:{metricIds:ids}});await load();closeDialog();toast('Состав и порядок метрик сохранены.');}
document.addEventListener('change',e=>{if(e.target.id==='metric-dimension'){metricDimension=e.target.value;openMetric(currentOverlay.id);}if(e.target.id==='employee-filter'){employeeId=e.target.value;render();}if(e.target.dataset.dashboardMetric){const id=e.target.dataset.dashboardMetric;dashboardDraft=e.target.checked?[...dashboardDraft,id]:dashboardDraft.filter(x=>x!==id);renderDashboardEditor();}});
document.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('[data-map-region]')){e.preventDefault();applyFilter('region',region===e.target.dataset.id?'all':e.target.dataset.id);}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const {action,id}=b.dataset;
 try{switch(action){
 case 'market':return applyFilter('market',id);case 'region':return applyFilter('region',id===region?'all':id);
 case 'metric-view':metricView=id;openMetric(currentOverlay.id);break;
 case 'employee':openEmployee(id);break;case 'staff-today':return applyFilter('period','today');case 'staff-day':return applyDateRange(id,id);
 case 'dashboard-edit':openDashboardEditor();break;case 'dashboard-remove':if(data.dashboard.required?.includes(id))return;dashboardDraft=dashboardDraft.filter(x=>x!==id);renderDashboardEditor();break;
 case 'dashboard-move-up':case 'dashboard-move-down':{const i=dashboardDraft.indexOf(id),j=i+(action==='dashboard-move-up'?-1:1);if(j>=0&&j<dashboardDraft.length)[dashboardDraft[i],dashboardDraft[j]]=[dashboardDraft[j],dashboardDraft[i]];renderDashboardEditor();break;}
 case 'dashboard-defaults':dashboardDraft=[...data.dashboard.defaults];renderDashboardEditor();break;
 case 'dashboard-save':b.disabled=true;try{await saveDashboard(dashboardDraft);}catch(err){b.disabled=false;throw err;}break;
 case 'dashboard-toggle':{if(data.dashboard.required?.includes(id)&&data.dashboard.metrics.includes(id))return toast('Это обязательный KPI.');const ids=data.dashboard.metrics.includes(id)?data.dashboard.metrics.filter(x=>x!==id):[...data.dashboard.metrics,id];if(!ids.length)return toast('На дашборде должна остаться хотя бы одна метрика.',true);b.disabled=true;try{await saveDashboard(ids);}catch(err){b.disabled=false;throw err;}break;}
 case 'review-order':await openOrderById(id);break;
 }}catch(error){toast(error.message,true);}
});

function splitPlot(points){const groups=[];let current=[];for(const point of points){if(point)current.push(point);else if(current.length){groups.push(current);current=[];}}if(current.length)groups.push(current);return groups;}

function sourceQualityPanel(){const q=data.qualityReport;return `<section class="panel source-quality"><div class="panel-header"><div><h2 class="panel-title">Свежесть и качество данных</h2><p class="panel-subtitle">Последнее изменение исходных фактов: ${date(data.source.updatedAt,true)}</p></div>${pill(q.missing||q.duplicates||q.invalid||q.reconciled?.mismatched?'Есть расхождения':'Проверки пройдены',q.missing||q.duplicates||q.invalid||q.reconciled?.mismatched?'warning':'good')}</div><div class="funnel">${[['Заказов',q.orders],['Пропуски ключей',q.missing],['Дубликаты ID',q.duplicates],['Расхождения ERP / 1С',q.reconciled?.mismatched??'—']].map(([l,n])=>`<div><strong>${n}</strong><p>${l}</p></div>`).join('')}</div><div class="table-scroll"><table><caption>Проверка каждого источника</caption><thead><tr><th>Источник</th><th>Обновлён</th><th>Записей</th><th>Пропусков</th><th>Дублей</th><th>Ошибок</th></tr></thead><tbody>${(q.sources||[]).map(s=>`<tr><td>${esc(s.file)}</td><td>${date(s.updatedAt,true)}</td><td>${s.rows}</td><td>${s.missing}</td><td>${s.duplicates}</td><td>${s.invalid}</td></tr>`).join('')}</tbody></table></div>${q.issues?.length?`<details><summary>Ошибки данных: ${q.issues.length}</summary><ul>${q.issues.slice(0,100).map(i=>`<li>${esc(i.file)}: строка ${i.row}, ${esc(i.field)} — ${esc(i.message)}</li>`).join('')}</ul></details>`:''}<div class="source-domains">${[['CRM / поддержка','customers.csv · interactions.csv · responses.csv','customerId / orderId'],['ERP / производство','orders.csv · process_orders.csv','orderId / productId'],['1С / финансы','finance_entries.csv','orderId / currency'],['HR / персонал','staff.csv · employees.csv','department / employeeId']].map(([name,files,links])=>`<div><strong>${name}</strong><span>${files}</span><small>Связи: ${links} · имитация</small></div>`).join('')}</div></section>`;}

async function openOrderById(id){const local=data.orders.find(o=>o.id===id);if(local)return openOrder(id);const result=await api('/api/orders/'+encodeURIComponent(id));openOrder(id,result.order);}

function hideReadonlyControls(){if(data&&!canManage())document.querySelectorAll('[data-action^="dashboard-"]').forEach(b=>b.hidden=true);}
function renderLogin(){closeDialog();document.title='Вход · Фотопринт';document.querySelector('#app').innerHTML=`<main class="login-shell"><section class="panel login-panel"><span class="eyebrow">ФОТОПРИНТ · КОНТУР</span><h1>Вход в дашборд</h1><p>Рабочие показатели и решения вашей команды</p><form id="login-form"><label class="form-field"><span>Логин</span><input name="username" autocomplete="username" required autofocus></label><label class="form-field"><span>Пароль</span><input name="password" type="password" autocomplete="current-password" required></label><p id="login-error" role="alert"></p><button class="btn btn-primary" type="submit">Войти${icon('arrow')}</button></form><small>Учётную запись предоставляет владелец локального сервера.</small></section></main>`;}
async function openProposals(){const {proposals}=await api('/api/v1/proposals');showDialog(dialogHeader('Изменения конфигурации','Предложения агента и ваши изменения. Применение требует подтверждения.')+`<div class="modal-body proposal-list">${proposals.length?proposals.map(p=>`<button class="proposal-row" data-action="proposal" data-id="${p.id}"><span><strong>${esc(p.payload.label||p.payload.id)}</strong><small>${esc(p.operation)} · версия ${p.baseVersion} → ${p.baseVersion+1} · ${date(p.createdAt,true)}</small></span>${pill(({pending:'Ожидает решения',applied:'Применено',cancelled:'Отменено'})[p.status],p.status==='applied'?'good':'')}${icon('right')}</button>`).join(''):empty('Предложений пока нет','Агент сможет подготовить их после подключения персонального токена.')}</div>`);}
async function openProposal(id){
 const r=await api('/api/v1/proposals/'+encodeURIComponent(id));reviewProposal={...r.proposal,confirmationToken:r.confirmationToken};const p=r.proposal,v=p.preview;
 const labels=ids=>(ids||[]).map(id=>data.kpis.find(k=>k.id===id)?.label||id).join(' · ');
 const metricDetail=p.kind==='metric'&&!v.removal?`<section class="formula-block"><span class="eyebrow">ФОРМУЛА</span><h3>${esc(v.formula)}</h3><div class="proposal-value">${v.value===null?'Нет данных':fmt(v.value)} <small>${esc(v.unit)}</small></div><p>Выборка: ${v.sampleSize} · ${esc(v.filters.from)} — ${esc(v.filters.to)} · ${esc(v.filters.market||'all')}</p><p>Область: ${esc(p.payload.scope.type==='company'?'Компания':p.payload.scope.department)} · Цель: ${p.payload.target??'—'}</p><div class="formula-meta">${v.sources.map(s=>esc(s.file)+' · '+date(s.updatedAt,true)).join('<br>')}</div>${v.freshness.stale?'<p class="delta negative">Источники старше 24 часов</p>':''}${v.warnings.length?'<p>Ограничения расчёта: '+esc(v.warnings.join(', '))+'</p>':''}</section>`:v.removal?'<p>Будет восстановлено отсутствие пользовательской конфигурации. Стандартные KPI остаются доступны.</p>':`<div class="proposal-diff"><section><span class="eyebrow">СЕЙЧАС</span><p>${esc(labels(p.before?.metricIds)||'Стандартный дашборд')}</p></section><section><span class="eyebrow">ПОСЛЕ ПОДТВЕРЖДЕНИЯ</span><p>${esc(labels(p.payload.metricIds))}</p></section></div>`;
 showDialog(dialogHeader(p.operation==='rollback'?'Подтвердить откат':'Проверить изменение',`${p.payload.label||p.payload.id} · версия ${p.baseVersion} → ${p.baseVersion+1}`,pill(p.status==='pending'?'Ожидает подтверждения':p.status==='applied'?'Применено':'Отменено'))+`<div class="modal-body proposal-review">${metricDetail}${p.kind==='metric'&&p.before?`<details><summary>Предыдущая формула</summary><pre>${esc(JSON.stringify(p.before.expression,null,2))}</pre></details>`:''}<p class="section-note">Автор: ${p.author==='agent'?'агент от вашего имени':'вы'} · предложение действительно до ${date(p.expiresAt,true)}. Изменение версии или источников потребует нового предпросмотра.</p></div><footer class="form-actions">${r.canConfirm?`<button class="btn" data-action="proposal-cancel" data-id="${p.id}">Отклонить</button>${p.kind==='metric'&&!v.removal?'<button class="btn" data-action="proposal-edit">Исправить</button>':''}<button class="btn btn-primary" data-action="proposal-confirm" data-id="${p.id}">${icon('check')}Подтверждаю изменение</button>`:`<button class="btn" data-action="close">Закрыть</button>`}</footer>`,true);
 currentOverlay={type:'proposal',id};
}
async function openAccess(){const {tokens}=await api('/api/auth/tokens');showDialog(dialogHeader('Доступ агента','Токен привязан к вашей учётной записи. Агент не может подтверждать изменения.')+`<div class="modal-body"><form id="token-form"><label class="form-field"><span>Название подключения</span><input name="label" value="hack_3" maxlength="80" required></label><p>Срок: 1 час. Разрешения: чтение каталога${canManage()?', предпросмотр и предложения':''}.</p><button class="btn btn-primary" type="submit">Создать персональный токен</button></form><div id="token-result"></div><h3>Активные подключения</h3>${tokens.map(t=>`<div class="proposal-row"><span><strong>${esc(t.label)}</strong><small>До ${date(t.expiresAt,true)}</small></span><button class="btn" data-action="token-revoke" data-id="${t.id}">Отозвать</button></div>`).join('')||'<p>Подключений нет</p>'}</div>`);}
async function openMetricEditor(definition=null,baseVersion=0){
 const fields=await api('/api/v1/fields');metricDraft={baseVersion,previousProposal:reviewProposal?.status==='pending'?reviewProposal.id:null};const d=definition||{id:'custom_'+key().replaceAll('-','').slice(0,8),label:'',source:'orders',expression:{op:'avg',field:'leadHours'},unit:'hours',target:36,better:'lower',scope:data.actor.role==='executive'?{type:'company'}:{type:'department',department:data.actor.departments[0]},description:''};
 showDialog(dialogHeader(definition?'Редактировать метрику':'Новая метрика','Формула проверяется на сервере до сохранения.')+`<form id="metric-config-form" data-draft-id="${definition?esc(definition.id):'new'}"><div class="modal-body config-form"><input name="id" type="hidden" value="${esc(d.id)}"><label class="form-field"><span>Название</span><input name="label" value="${esc(d.label)}" minlength="3" maxlength="100" required></label><div class="form-row"><label class="form-field"><span>Источник</span><select name="source">${fields.sources.map(s=>`<option value="${s.source}" ${s.source===d.source?'selected':''}>${s.file}</option>`).join('')}</select></label><label class="form-field"><span>Единица</span><select name="unit">${fields.units.map(u=>`<option ${u===d.unit?'selected':''}>${u}</option>`).join('')}</select></label></div><label class="form-field"><span>Область</span><select name="scope" ${definition?'disabled':''}>${data.actor.role==='executive'?`<option value="company" ${d.scope.type==='company'?'selected':''}>Компания</option>`:''}${data.actor.departments.map(id=>`<option value="${id}" ${d.scope.department===id?'selected':''}>${esc(data.departments.find(x=>x.id===id)?.name||id)}</option>`).join('')}</select></label><label class="form-field"><span>Формула (структурированное выражение)</span><textarea name="expression" rows="6" required spellcheck="false">${esc(JSON.stringify(d.expression,null,2))}</textarea></label><details><summary>Доступные поля и операции</summary><p>count, sum, avg, min, max, percentile (p: 50, 90, 95, 99), add, subtract, multiply, divide, constant.</p>${fields.sources.map(s=>`<p><b>${s.file}</b>: ${s.fields.map(f=>esc(f.name)).join(', ')}</p>`).join('')}</details><div class="form-row"><label class="form-field"><span>Цель</span><input name="target" type="number" step="any" value="${d.target??''}"></label><label class="form-field"><span>Лучший результат</span><select name="better"><option value="higher" ${d.better==='higher'?'selected':''}>Больше</option><option value="lower" ${d.better==='lower'?'selected':''}>Меньше</option></select></label></div><label class="form-field"><span>Описание</span><input name="description" maxlength="500" value="${esc(d.description)}"></label><p id="metric-config-error" role="alert"></p></div><footer class="form-actions"><button class="btn" type="button" data-action="close">Отмена</button><button class="btn btn-primary" type="submit">Проверить и просмотреть</button></footer></form>`,true);
 metricDraft.scope=d.scope;
}
async function openHistory(resource){const {revisions}=await api('/api/v1/history?resource='+encodeURIComponent(resource));const current=revisions.at(-1)?.version||0;showDialog(dialogHeader('Версии конфигурации',resource)+`<div class="modal-body">${revisions.map(r=>`<div class="proposal-row"><span><strong>Версия ${r.version}</strong><small>${date(r.at,true)} · ${esc(r.operation)}</small></span>${r.version<current?`<button class="btn" data-action="rollback" data-resource="${esc(resource)}" data-version="${r.version}" data-current="${current}">Предпросмотр отката</button>`:pill('Текущая','good')}</div>`).join('')}${current?`<button class="btn" data-action="rollback" data-resource="${esc(resource)}" data-version="0" data-current="${current}">К исходной конфигурации</button>`:empty('Сохранённых версий пока нет')}</div>`);}
document.addEventListener('submit',async e=>{
 const form=e.target;if(!['login-form','token-form','metric-config-form'].includes(form.id))return;e.preventDefault();const button=form.querySelector('[type="submit"]');button.disabled=true;
 try{
  const values=Object.fromEntries(new FormData(form));
  if(form.id==='login-form'){const r=await api('/api/auth/login',{method:'POST',body:values});csrfToken=r.csrf;await load();const id=new URLSearchParams(location.search).get('proposal');if(id)await openProposal(id);}
  if(form.id==='token-form'){const r=await api('/api/auth/tokens',{method:'POST',body:{label:values.label,expiresIn:3600,scopes:canManage()?['catalog:read','changes:propose']:['catalog:read']}});document.querySelector('#token-result').innerHTML=`<label class="form-field"><span>Скопируйте токен в настройку интеграции hack_3</span><textarea readonly rows="2">${esc(r.token)}</textarea></label><p>API на этом компьютере: http://127.0.0.1:8080/api/v1</p>`;}
  if(form.id==='metric-config-form'){let expression;try{expression=JSON.parse(values.expression);}catch{throw new Error('Формула должна быть корректным JSON.');}const scope=form.elements.scope.disabled?metricDraft.scope:values.scope==='company'?{type:'company'}:{type:'department',department:values.scope};const definition={id:values.id,label:values.label,source:values.source,expression,unit:values.unit,scope,target:values.target===''?null:Number(values.target),better:values.better,description:values.description};const r=await api('/api/v1/proposals',{method:'POST',key:pendingKey,body:{kind:'metric',definition,baseVersion:metricDraft.baseVersion,filters:Object.fromEntries(params())}});clearFormDraft(form);await openProposal(r.proposal.id);}
 }catch(error){const slot=form.querySelector('[role="alert"]');if(slot)slot.textContent=error.message;else toast(error.message,true);}finally{button.disabled=false;}
});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const {action,id}=b.dataset;try{
 if(action==='logout'){await api('/api/auth/logout',{method:'POST',body:{}});csrfToken='';data=null;renderLogin();}
 if(action==='access')await openAccess();
 if(action==='token-revoke'){await api('/api/auth/tokens/'+id+'/revoke',{method:'POST',body:{}});await openAccess();}
 if(action==='proposals')await openProposals();if(action==='proposal')await openProposal(id);
 if(action==='proposal-confirm'){b.disabled=true;await api('/api/v1/proposals/'+id+'/confirm',{method:'POST',key:'confirm-'+id,body:{confirm:true,confirmationToken:reviewProposal.confirmationToken}});closeDialog();history.replaceState(null,'',location.pathname+location.hash);await load();toast('Изменение подтверждено и сохранено.');}
 if(action==='proposal-cancel'){b.disabled=true;await api('/api/v1/proposals/'+id+'/cancel',{method:'POST',body:{}});await openProposals();}
 if(action==='metric-new'){reviewProposal=null;await openMetricEditor();}
 if(action==='proposal-edit')await openMetricEditor(reviewProposal.payload,reviewProposal.baseVersion);
 if(action==='config-history')await openHistory(b.dataset.resource);
 if(action==='metric-update'){const {metrics}=await api('/api/v1/catalog');const k=metrics.find(k=>k.id===id);reviewProposal=null;await openMetricEditor(k.definition,k.version);}
 if(action==='rollback'){const r=await api('/api/v1/proposals',{method:'POST',body:{kind:'rollback',resource:b.dataset.resource,baseVersion:Number(b.dataset.current),targetVersion:Number(b.dataset.version),filters:Object.fromEntries(params())}});clearFormDraft(form);await openProposal(r.proposal.id);}
 }catch(error){b.disabled=false;toast(error.message,true);}});

function shiftPanel(){const shifts=data.shifts||[];return `<section class="panel"><div class="panel-header"><h2>Календарь смен</h2><p>Синтетический график · Europe/Minsk · доступные часы учитывают плановое обслуживание</p></div><div class="table-scroll"><table><thead><tr><th>Начало</th><th>Конец</th><th>Направление</th><th>Штат / план</th><th>Отсутствуют</th><th>Доступные часы</th></tr></thead><tbody>${shifts.slice(0,100).map(s=>`<tr><td>${date(s.startsAt,true)}</td><td>${date(s.endsAt,true)}</td><td>${esc(data.departments.find(d=>d.id===s.department)?.name||s.department)}</td><td>${s.actual} / ${s.planned}</td><td>${s.absent}</td><td>${fmt(s.availableHours)}</td></tr>`).join('')||'<tr><td colspan="6">В выбранном периоде смен нет</td></tr>'}</tbody></table></div>${shifts.length>100?`<p>Показаны 100 из ${shifts.length} смен. Полный набор — shifts.csv.</p>`:''}</section>`;}
